// 历史人物：15 世纪至 17 世纪初（文艺复兴、大航海与宗教改革时代）。
// 站点文案依次为地点、一句话标题、讲解；sea 表示海路，via 为避开陆地的中间航点。
import type { Figure } from '../../types.ts';
import { w } from './waypoint.ts';

export const FIGURES_RENAISSANCE: Figure[] = [
  {
    id: 'joan-of-arc',
    name: { zh: '圣女贞德', en: 'Joan of Arc' },
    birth: 1412, death: 1431, approx: true,
    title: { zh: '法国民族英雄', en: 'French national heroine' },
    region: 'europe',
    lineage: 'france',
    sprite: 'flag',
    summary: {
      zh: '英法百年战争中的法国民族英雄。这位农家少女自称受到神启，1429年说服王太子查理让她随军出征，成功解除奥尔良之围，并护送查理七世在兰斯加冕。次年被俘，1431年在鲁昂被宗教法庭以异端罪名处以火刑，年仅19岁。1456年获平反，1920年被天主教会封为圣人。',
      en: "French national heroine of the Hundred Years' War. A peasant girl who said she was guided by voices from God, she persuaded the Dauphin Charles in 1429 to let her ride with his army, helped raise the siege of Orléans and escorted him to Reims to be crowned as Charles VII. Captured the following year, she was tried for heresy by a church court at Rouen and burned at the stake in 1431, aged about 19. The verdict was annulled in 1456 and she was canonised in 1920.",
    },
    route: [
      w(1412, 5.67, 48.44,
        ['栋雷米（今法国孚日省栋雷米拉皮塞勒）', '生于法国东北部农家', '贞德约于1412年生在默兹河畔的栋雷米村，父亲雅克·达克是当地较殷实的农民。她不识字，自幼帮家里纺线、放牧。当时法国北部大半已落入英格兰及其盟友勃艮第人之手。'],
        ['Domrémy (now Domrémy-la-Pucelle, Vosges, France)', 'Born to a farming family in north-eastern France', "Joan was born around 1412 in the village of Domrémy on the Meuse, the daughter of Jacques d'Arc, a fairly prosperous farmer. She never learned to read and grew up spinning and tending animals, at a time when much of northern France was in English and Burgundian hands."],
        { wiki: { zh: '栋雷米拉皮塞勒', en: 'Domrémy-la-Pucelle' } }),
      w(1425, 5.67, 48.44,
        ['栋雷米', '约13岁时自称初次听到“声音”', '据贞德在审判中的自述，她约13岁那年夏天在父亲的园子里第一次听到“声音”，后来认定来者是大天使米迦勒、圣凯瑟琳和圣玛格丽特。声音起初只劝她做个好姑娘、常去教堂，后来一再催促她“到法兰西去”，解救奥尔良。'],
        ['Domrémy', 'First hears her "voices" at about thirteen', "By her own account at her trial, Joan was about thirteen when she first heard a voice in her father's garden one summer day. She came to identify her visitors as the archangel Michael, St Catherine and St Margaret. At first they told her only to be good and go to church; later they urged her to go into France and relieve Orléans."]),
      w(1429, 5.667, 48.602,
        ['沃库勒尔', '说服守将博德里库尔派人护送', '1428年贞德首次求见当地守将罗贝尔·德·博德里库尔时被打发回家。1429年初她再度前来，终于获准启程。她剪短头发、换上男装，由六名随从护送，用约11天穿过敌方控制的地区前往希农。'],
        ['Vaucouleurs', 'Wins an escort from the garrison commander', 'Robert de Baudricourt, the local captain, sent Joan home when she first approached him in 1428. When she came back early in 1429 he relented. With her hair cropped and dressed as a man, she set out with six companions on a ride of about eleven days across hostile territory to Chinon.']),
      w(1429, 0.24, 47.17,
        ['希农', '觐见王太子查理', '1429年2月底至3月初，贞德抵达王太子所在的希农城堡。相传查理混在廷臣当中试探，她仍径直认出了他。她声称奉上帝之命来解奥尔良之围，并要带他去兰斯加冕。'],
        ['Chinon', 'Meets the Dauphin Charles', "Joan reached the Dauphin's court at the castle of Chinon around the turn of February and March 1429. According to tradition Charles hid among his courtiers to test her, and she picked him out at once. She told him she had been sent by God to relieve Orléans and to see him crowned at Reims."],
        { wiki: { zh: '希农城堡', en: 'Château de Chinon' } }),
      w(1429, 0.34, 46.58,
        ['普瓦捷', '接受神学家审查', '查理把贞德送到普瓦捷，由一批神学家和教士盘问了约三周。他们没有发现她有任何不端之处，建议让她到奥尔良一试。随后她在图尔领到一副铠甲和一面写有“耶稣、玛利亚”字样的白色军旗。'],
        ['Poitiers', 'Examined by theologians', 'Charles sent Joan to Poitiers, where churchmen and theologians questioned her for about three weeks. They found nothing but good in her and advised that she be put to the test at Orléans. At Tours she was then fitted with armour and given a white standard bearing the names of Jesus and Mary.']),
      w(1429, 1.91, 47.9,
        ['奥尔良', '率军解奥尔良之围，号称“奥尔良的少女”', '奥尔良自1428年10月起被英军围困。贞德随援军于4月29日入城，此后数日法军连克城外堡垒；5月7日攻打图雷勒堡时她肩部中箭，仍返回阵前。次日英军撤围而去。'],
        ['Orléans', 'Helps raise the siege and becomes the "Maid of Orléans"', 'The English had besieged Orléans since October 1428. Joan entered the city with a relief force on 29 April, and in the days that followed the French stormed the surrounding forts. Wounded by an arrow at Les Tourelles on 7 May, she returned to the fight, and the English withdrew the next day.'],
        { event: 'siege-of-orleans' }),
      w(1429, 1.695, 48.048,
        ['帕提', '法军在帕提大破英军', '解围后法军沿卢瓦尔河连克雅尔若、默恩和博让西。6月18日，法军前锋在帕提追上撤退中的英军，趁其长弓手尚未列阵发起冲锋。英军溃败，主将塔尔博特被俘，通往兰斯的道路由此打开。'],
        ['Patay', 'The French rout the English at Patay', 'After Orléans the French took Jargeau, Meung and Beaugency along the Loire. On 18 June their vanguard caught the retreating English near Patay and charged before the longbowmen could form up. The English were routed and their commander John Talbot was captured, opening the road to Reims.'],
        { wiki: { zh: '帕提战役', en: 'Battle of Patay' } }),
      w(1429, 4.07, 48.3,
        ['特鲁瓦', '进军兰斯途中迫降特鲁瓦', '6月底，贞德随查理的军队自日安出发，穿越勃艮第人控制的香槟地区。特鲁瓦起初闭门不纳，军中粮食将尽，不少人主张退兵；贞德力主备战攻城，城中于7月上旬开门归顺。'],
        ['Troyes', 'Troyes submits on the march to Reims', "At the end of June the royal army left Gien and marched through Burgundian-held Champagne. Troyes at first shut its gates, and with supplies running low many of the king's counsellors urged retreat. Joan pressed for an assault, and as preparations began the town came to terms in early July."]),
      w(1429, 4.03, 49.25,
        ['兰斯', '护送查理七世在兰斯大教堂加冕', '7月17日，查理在历代法王加冕之地兰斯大教堂受膏加冕，是为查理七世，贞德手持军旗立于祭坛旁。相对于英方所立的幼主亨利六世，这场加冕礼大大增强了查理的正统地位。'],
        ['Reims', 'Sees Charles VII crowned in Reims Cathedral', 'On 17 July 1429 Charles was anointed and crowned in Reims Cathedral, the traditional coronation church of French kings, with Joan standing near the altar holding her standard. The ceremony greatly strengthened his claim against the boy-king Henry VI of England, whom the English put forward as king of France.'],
        { wiki: { zh: '兰斯主教座堂', en: 'Reims Cathedral' } }),
      w(1429, 2.335, 48.864,
        ['巴黎（圣奥诺雷门）', '强攻巴黎失利，腿部中箭', '9月8日，贞德与阿朗松公爵率军攻打英、勃艮第一方控制的巴黎。她在圣奥诺雷门外的壕沟边被弩箭射中大腿，攻势至夜未果。次日查理七世下令撤军，不久便解散了这支军队。'],
        ['Paris (Porte Saint-Honoré)', 'Wounded in a failed assault on Paris', 'On 8 September Joan and the Duke of Alençon attacked Paris, which was held for the Anglo-Burgundian side. She was hit in the thigh by a crossbow bolt at the moat before the Porte Saint-Honoré, and the assault failed. Charles VII ordered a withdrawal the next day and soon disbanded the army.']),
      w(1429, 3.12, 46.79,
        ['圣皮埃尔勒穆捷', '攻克圣皮埃尔勒穆捷', '秋天，宫廷派贞德去清剿盘踞卢瓦尔河上游的雇佣兵首领。11月初她攻下圣皮埃尔勒穆捷，随后围攻拉沙里泰，却因天寒、缺粮缺饷，约一个月后无功而返。12月，查理七世封她全家为贵族。'],
        ['Saint-Pierre-le-Moûtier', 'Takes Saint-Pierre-le-Moûtier', 'That autumn the court sent Joan against a mercenary captain who held towns on the upper Loire. She stormed Saint-Pierre-le-Moûtier in early November, but the siege of La Charité that followed was abandoned after about a month for want of money and supplies in the winter cold. In December Charles VII ennobled her family.']),
      w(1430, 2.83, 49.42,
        ['贡比涅', '被勃艮第人俘获，后转交英军', '1430年5月，贞德率少数人马驰援被勃艮第军围困的贡比涅。5月23日傍晚她出城突袭，退回时城门已经关闭，她被拉下马来，成了勃艮第一方的贵族卢森堡的让手下的俘虏。'],
        ['Compiègne', 'Captured by the Burgundians, later sold to the English', 'In May 1430 Joan hurried with a small force to Compiègne, which the Burgundians were besieging. During a sortie on the evening of 23 May she covered the retreat, but the town gate was closed before she could get back in. Pulled from her horse, she became the prisoner of a follower of John of Luxembourg.']),
      w(1430, 3.31, 49.99,
        ['博尔沃阿尔', '囚于博尔沃阿尔城堡，跳塔逃亡未果', '贞德被关在卢森堡的让的博尔沃阿尔城堡数月。得知自己将被交给英格兰人，她从塔楼高处跳下，摔得昏迷却没有重伤。同年秋，英方以1万图尔里弗尔的价钱把她买走。'],
        ['Beaurevoir', 'Leaps from a tower in a bid to escape', "Joan was held for several months in John of Luxembourg's castle at Beaurevoir. Learning that she was to be handed over to the English, she jumped from a high tower and was found stunned but not seriously hurt. That autumn the English bought her for 10,000 livres tournois."]),
      w(1431, 1.0944, 49.4464,
        ['鲁昂（鲁昂城堡）', '在鲁昂受宗教法庭审判', '贞德于1430年底被押到英军在诺曼底的首府鲁昂。1431年初，亲英的博韦主教皮埃尔·科雄开庭审判，围绕她的“声音”和男装反复讯问。5月24日她在威吓下签字悔过，数日后又翻供，重新穿上男装。'],
        ['Rouen (Rouen Castle)', 'Tried by a church court at Rouen', 'Joan was brought at the end of 1430 to Rouen, the English headquarters in Normandy. Early in 1431 Pierre Cauchon, the pro-English bishop of Beauvais, opened her trial, which dwelt on her voices and her male dress. On 24 May she signed an abjuration under threat, but within days she withdrew it and resumed male clothing.'],
        { wiki: { zh: '圣女贞德的审判', en: 'Trial of Joan of Arc' } }),
      w(1431, 1.1, 49.44,
        ['鲁昂（老集市广场）', '以异端罪名被处火刑', '1431年5月30日，贞德被判为“重陷异端者”，在鲁昂老集市广场被烧死，骨灰撒入塞纳河。1456年，经教皇授权的复审宣布原判无效；1920年她被封为圣人，成为法国的主保圣人之一。'],
        ['Rouen (Old Market Square)', 'Burned at the stake for heresy', 'On 30 May 1431 Joan was condemned as a relapsed heretic and burned in the Old Market Square of Rouen; her ashes were thrown into the Seine. A retrial authorised by the pope annulled the verdict in 1456. She was canonised in 1920 and is one of the patron saints of France.']),
    ],
    wiki: { zh: '圣女贞德', en: 'Joan of Arc' },
  },
  {
    id: 'mehmed-ii',
    name: { zh: '穆罕默德二世', en: 'Mehmed II' },
    birth: 1432, death: 1481,
    title: { zh: '奥斯曼帝国苏丹', en: 'Ottoman sultan' },
    region: 'west-asia',
    lineage: 'ottoman',
    sprite: 'cannon',
    summary: {
      zh: '奥斯曼帝国苏丹，号称“征服者”。1453年他以巨型火炮攻陷君士坦丁堡，终结了延续千年的拜占庭帝国，并将都城迁至此地。此后近三十年间，他继续征服塞尔维亚、摩里亚、特拉布宗、波斯尼亚等地，重建伊斯坦布尔并兴建托普卡帕宫，奠定了奥斯曼帝国横跨欧亚的版图。',
      en: 'Ottoman sultan known as "the Conqueror". In 1453, aged 21, he took Constantinople with the help of giant cannon, ending the thousand-year Byzantine Empire, and made the city his capital. Over the next three decades he annexed Serbia, the Morea, Trebizond and Bosnia, rebuilt Istanbul and began Topkapi Palace, establishing the Ottoman Empire as a power spanning south-eastern Europe and Anatolia.',
    },
    route: [
      w(1432, 26.56, 41.68,
        ['埃迪尔内', '生于奥斯曼帝国都城埃迪尔内', '1432年3月30日，穆罕默德生于埃迪尔内的宫廷，是苏丹穆拉德二世之子。按照奥斯曼王子的惯例，他幼年即被派往安纳托利亚的行省，在师傅辅佐下名义上担任总督，学习治理。'],
        ['Edirne', 'Born in the Ottoman capital, Edirne', 'Mehmed was born on 30 March 1432 at the court in Edirne, a son of Sultan Murad II. Following Ottoman custom he was sent as a young boy to the Anatolian provinces, where he served as nominal governor under the guidance of tutors and learned the business of rule.']),
      w(1444, 26.56, 41.68,
        ['埃迪尔内', '12岁首次即位', '1444年，穆拉德二世与匈牙利议和后退位，把苏丹之位让给12岁的穆罕默德。一支十字军随即毁约南下；穆拉德复出统兵，同年11月在瓦尔纳将其击溃。1446年近卫军哗变后，穆拉德重登大位。'],
        ['Edirne', 'First becomes sultan at the age of twelve', 'In 1444 Murad II made peace with Hungary and abdicated in favour of his twelve-year-old son. A crusading army promptly broke the truce and marched south, and Murad returned to command the Ottoman forces, destroying it at Varna that November. After a Janissary revolt in 1446 he resumed the throne.']),
      w(1446, 27.43, 38.61,
        ['马尼萨', '退居马尼萨任总督', '被父亲取代后，穆罕默德回到安纳托利亚西部的马尼萨任总督，在这里度过约五年。他随学者研习伊斯兰学问、历史与地理，也随父亲出征，参加了1448年的第二次科索沃之战。'],
        ['Manisa', 'Sent back to govern Manisa', 'Displaced by his father, Mehmed returned to western Anatolia as governor of Manisa, where he spent some five years. He studied Islamic learning, history and geography with his tutors and also joined his father on campaign, including the second battle of Kosovo in 1448.']),
      w(1451, 26.56, 41.68,
        ['埃迪尔内', '再度即位为苏丹', '1451年2月穆拉德二世去世，18岁的穆罕默德从马尼萨赶回埃迪尔内继位。他与威尼斯、匈牙利续订和约，稳住安纳托利亚的卡拉曼，随即着手筹备夺取君士坦丁堡。'],
        ['Edirne', 'Becomes sultan for the second time', 'Murad II died in February 1451 and the eighteen-year-old Mehmed hurried from Manisa to Edirne to take the throne. He renewed peace with Venice and Hungary, checked the Karamanids in Anatolia, and then turned to preparing the capture of Constantinople.']),
      w(1452, 29.056, 41.085,
        ['鲁梅利堡（今伊斯坦布尔）', '在博斯普鲁斯海峡西岸修建要塞', '1452年，穆罕默德在海峡最窄处的欧洲一岸筑起鲁梅利堡，仅用约四个月完工，与对岸曾祖父巴耶济德一世所建的安纳托利亚堡相望。堡上火炮可以封锁航道，切断君士坦丁堡来自黑海的粮食和援兵。'],
        ['Rumelihisarı (now in Istanbul)', 'Builds a fortress on the Bosphorus', 'In 1452 Mehmed built Rumelihisarı on the European shore at the narrowest point of the Bosphorus, finishing it in about four months. Facing the older Anadoluhisarı across the water, its guns could close the strait and cut Constantinople off from grain and reinforcements from the Black Sea.'],
        { wiki: { zh: '如梅利堡垒', en: 'Rumelihisarı' } }),
      w(1453, 28.98, 41.01,
        ['君士坦丁堡（今伊斯坦布尔）', '攻陷君士坦丁堡，号称“征服者”', '围城始于1453年4月初。匈牙利工匠乌尔班铸造的巨炮连日轰击狄奥多西城墙，奥斯曼人还把数十艘战船从陆上拖入金角湾。5月29日城破，末代皇帝君士坦丁十一世战死，穆罕默德入城后把圣索菲亚大教堂改为清真寺。'],
        ['Constantinople (now Istanbul)', 'Takes Constantinople and earns the name "Conqueror"', 'The siege began in early April 1453. Great cannon cast by the Hungarian founder Orban battered the Theodosian Walls, and the Ottomans hauled dozens of ships overland into the Golden Horn. The city fell on 29 May; the last emperor, Constantine XI, died in the fighting, and Hagia Sophia was turned into a mosque.'],
        { event: 'fall-of-constantinople' }),
      w(1456, 20.46, 44.82,
        ['贝尔格莱德', '围攻贝尔格莱德失利', '1456年7月，穆罕默德率大军围攻匈牙利王国南疆的门户贝尔格莱德。匈雅提·亚诺什率援军突破多瑙河上的封锁，与方济各会士卡佩斯特拉诺召集的十字军一道反击，奥斯曼军败退，苏丹本人也负了伤。'],
        ['Belgrade', 'Fails to take Belgrade', 'In July 1456 Mehmed besieged Belgrade, the southern gateway of the Kingdom of Hungary. John Hunyadi broke the Ottoman blockade on the Danube, and his troops, together with crusaders rallied by the Franciscan John of Capistrano, drove the besiegers back. The sultan himself was wounded.']),
      w(1459, 28.984, 41.012,
        ['伊斯坦布尔', '兴建托普卡帕宫，重建都城', '征服之后，穆罕默德从各地迁来穆斯林、希腊人、亚美尼亚人和犹太人，充实这座人口凋敝的城市，并承认东正教牧首的地位。1459年起，他在古卫城所在的岬角上兴建托普卡帕宫，又修建了法提赫清真寺和大巴扎。'],
        ['Istanbul', 'Begins Topkapi Palace and rebuilds his capital', 'After the conquest Mehmed repopulated the half-empty city with Muslims, Greeks, Armenians and Jews brought from across his lands and recognised the Orthodox patriarch. From 1459 he built Topkapi Palace on the promontory of the ancient acropolis, and he also founded the Fatih Mosque and the Grand Bazaar.'],
        { wiki: { zh: '托普卡帕宫', en: 'Topkapı Palace' } }),
      w(1460, 22.37, 37.07,
        ['米斯特拉斯（希腊伯罗奔尼撒）', '吞并摩里亚专制国', '拜占庭末代皇帝的两个弟弟仍统治着伯罗奔尼撒的摩里亚。1458年穆罕默德首度南征，归途中游览了雅典卫城；1460年他再度亲征，5月米斯特拉斯开城投降，拜占庭在希腊本土的统治就此结束。'],
        ['Mystras (Peloponnese, Greece)', 'Annexes the Despotate of the Morea', 'Two brothers of the last emperor still ruled the Morea in the Peloponnese. Mehmed campaigned there in 1458, visiting the Acropolis of Athens on his way home, and returned in person in 1460. Mystras surrendered that May, ending Byzantine rule on the Greek mainland.'],
        { wiki: { zh: '米斯特拉斯', en: 'Mystras' } }),
      w(1461, 39.72, 41.0,
        ['特拉布宗', '灭特拉布宗帝国', '1461年，穆罕默德沿黑海南岸东进，先迫降锡诺普，再翻越本都山脉，与舰队水陆合围特拉布宗。8月，皇帝大卫·科穆宁开城投降，拜占庭的最后一个继承国宣告灭亡。'],
        ['Trebizond (now Trabzon)', 'Ends the Empire of Trebizond', 'In 1461 Mehmed marched east along the Black Sea, taking Sinope by surrender and then crossing the Pontic mountains while his fleet blockaded Trebizond from the sea. In August Emperor David Komnenos surrendered the city, extinguishing the last Byzantine successor state.']),
      w(1462, 25.46, 44.93,
        ['特尔戈维什泰（今罗马尼亚）', '征讨瓦拉几亚大公弗拉德三世', '瓦拉几亚大公“穿刺公”弗拉德三世拒纳贡赋，并袭扰多瑙河以南，1462年穆罕默德亲率大军北渡。6月弗拉德夜袭苏丹大营未能得手；奥斯曼军抵达其都城特尔戈维什泰时，城外是成片被施以穿刺刑的尸体。弗拉德不久失位。'],
        ['Târgoviște (Romania)', 'Campaigns against Vlad III of Wallachia', "Vlad III \"the Impaler\" of Wallachia had stopped paying tribute and raided south of the Danube, and in 1462 Mehmed crossed the river against him. A night attack on the sultan's camp in June failed to kill him. Outside the capital, Târgoviște, the Ottomans found a field of impaled bodies; Vlad soon lost his throne."]),
      w(1463, 17.27, 44.34,
        ['亚伊采（今波黑）', '征服波斯尼亚王国', '1463年春，穆罕默德挥师西进，波斯尼亚各城在数周内相继陷落。国王斯特凡·托马舍维奇在克柳奇投降后被押至亚伊采附近处死，波斯尼亚王国灭亡。同年，威尼斯与奥斯曼开始了长达十六年的战争。'],
        ['Jajce (Bosnia and Herzegovina)', 'Conquers the Kingdom of Bosnia', 'In spring 1463 Mehmed marched west and the Bosnian strongholds fell within weeks. King Stephen Tomašević surrendered at Ključ and was executed near Jajce, ending the Bosnian kingdom. That same year Venice went to war with the Ottomans, a conflict that would last sixteen years.']),
      w(1470, 23.6, 38.46,
        ['内格罗蓬特（今希腊哈尔基斯）', '夺取威尼斯的内格罗蓬特', '优卑亚岛上的内格罗蓬特是威尼斯在爱琴海最重要的基地。1470年夏，穆罕默德率陆军南下，与一支庞大的舰队会合，在海峡上架起浮桥攻城。7月城陷，消息震动了整个意大利。'],
        ['Negroponte (now Chalcis, Greece)', 'Takes Negroponte from Venice', "Negroponte on the island of Euboea was Venice's chief base in the Aegean. In summer 1470 Mehmed brought his army south to meet a large Ottoman fleet and threw a bridge of boats across the narrow strait to attack the town. It fell in July, a loss that alarmed all Italy."]),
      w(1473, 40.02, 39.97,
        ['奥特卢克贝利（今土耳其埃尔津詹省）', '击败白羊王朝的乌尊·哈桑', '白羊王朝君主乌尊·哈桑控制着伊朗和安纳托利亚东部，并与威尼斯结盟。1473年8月11日，两军在埃尔津詹附近的奥特卢克贝利决战，奥斯曼军的火炮和火枪击溃了对方的骑兵，东部边境的威胁由此解除。'],
        ['Otlukbeli (Erzincan Province, Turkey)', 'Defeats Uzun Hasan of the Aq Qoyunlu', "Uzun Hasan, ruler of the Aq Qoyunlu, held Iran and eastern Anatolia and had allied himself with Venice. On 11 August 1473 the two armies met at Otlukbeli near Erzincan, where Ottoman cannon and handguns broke the Turkmen cavalry and secured Mehmed's eastern frontier."]),
      w(1478, 19.4936, 42.0464,
        ['斯库台（今阿尔巴尼亚斯库台）', '亲征阿尔巴尼亚，围攻斯库台', '斯坎德培1468年去世后，阿尔巴尼亚的抵抗渐趋瓦解。1478年穆罕默德亲率大军迫降克鲁亚，并猛攻威尼斯人据守的斯库台罗扎法城堡而未克。次年初威尼斯求和，割让斯库台并答应每年缴纳一笔款项。'],
        ['Scutari (now Shkodër, Albania)', 'Leads the siege of Shkodër in Albania', 'Albanian resistance weakened after the death of Skanderbeg in 1468. In 1478 Mehmed came in person, received the surrender of Krujë and assaulted the Venetian-held castle of Rozafa at Shkodër without success. Venice made peace early the next year, ceding Shkodër and agreeing to an annual payment.'],
        { wiki: { zh: '罗扎法城堡', en: 'Rozafa Castle' } }),
      w(1480, 28.984, 41.012,
        ['伊斯坦布尔', '请威尼斯画家贝利尼入宫作画', '与威尼斯媾和后，穆罕默德请来画家真蒂莱·贝利尼，一般认为出自其手的苏丹肖像今藏伦敦国家美术馆。1480年，奥斯曼舰队围攻罗得岛的医院骑士团失利，另一支军队则渡海攻占了意大利南端的奥特朗托。'],
        ['Istanbul', 'Invites the Venetian painter Gentile Bellini to court', 'Once peace was made with Venice, Mehmed invited the painter Gentile Bellini to his court; the portrait of the sultan attributed to him is now in the National Gallery, London. In 1480 an Ottoman fleet failed to take Rhodes from the Knights Hospitaller, while another force seized Otranto in southern Italy.']),
      w(1481, 29.43, 40.8,
        ['盖布泽', '出征途中病逝', '1481年春，穆罕默德率军渡过海峡东行，目的地秘而不宣。5月3日他在盖布泽附近的营地去世，时年49岁。遗体运回伊斯坦布尔，葬于法提赫清真寺；其子巴耶济德与杰姆随即争夺大位。'],
        ['Gebze', 'Dies on campaign', 'In spring 1481 Mehmed crossed to Anatolia at the head of an army whose destination he kept secret. He died in camp near Gebze on 3 May, aged 49, and was buried at the Fatih Mosque in Istanbul. His sons Bayezid and Cem then fought over the succession.']),
    ],
    wiki: { zh: '穆罕默德二世', en: 'Mehmed II' },
  },
  {
    id: 'columbus',
    name: { zh: '哥伦布', en: 'Christopher Columbus' },
    birth: 1451, death: 1506, approx: true,
    title: { zh: '航海家', en: 'Navigator' },
    region: 'europe',
    lineage: 'spain',
    sprite: 'ship',
    summary: {
      zh: '意大利热那亚航海家。在西班牙天主教双王资助下，他于1492年横渡大西洋，抵达巴哈马群岛、古巴和伊斯帕尼奥拉岛，此后又三次远航，到过加勒比海各岛和中、南美洲海岸。他至死坚信自己到达的是亚洲。他的航行开启了欧洲对美洲的殖民，也给原住民带来了深重灾难。',
      en: 'Genoese navigator. Sailing for the Catholic Monarchs of Spain, he crossed the Atlantic in 1492 and reached the Bahamas, Cuba and Hispaniola, and he made three further voyages to the Caribbean and the coasts of Central and South America. He died still believing he had reached Asia. His voyages opened the way to the European colonisation of the Americas and brought catastrophe to their indigenous peoples.',
    },
    route: [
      w(1451, 8.93, 44.41,
        ['热那亚', '生于热那亚共和国', '哥伦布约于1451年生在热那亚，父亲多梅尼科是毛织工，兼营小买卖。他没受过多少正规教育，十几岁就随商船出海，据他自述曾远航至爱琴海上热那亚人控制的希俄斯岛。'],
        ['Genoa', 'Born in the Republic of Genoa', 'Columbus was born in Genoa around 1451, the son of Domenico Colombo, a wool weaver and small trader. He had little formal schooling and went to sea in his teens on merchant ships, sailing by his own account as far as the Genoese-held island of Chios in the Aegean.']),
      w(1476, -8.67, 37.1,
        ['拉古什外海（葡萄牙圣维森特角附近）', '商船队遇袭，游泳上岸', '1476年8月，哥伦布随一支驶往英格兰的热那亚商船队出海，在圣维森特角附近遭法国私掠舰队袭击，所乘之船起火沉没。据其子费尔南多记述，他抱着一支船桨游了数海里，才在拉古什附近上岸。'],
        ['Off Lagos (near Cape St Vincent, Portugal)', 'Swims ashore after his convoy is attacked', 'In August 1476 Columbus sailed with a Genoese convoy bound for England. Off Cape St Vincent it was attacked by a French privateer fleet, and his ship burned and sank. According to his son Ferdinand, he clung to an oar and swam several miles to the shore near Lagos.'],
        { sea: true, via: [[6.5, 42.0], [4.8, 39.3], [1.0, 37.6], [-2.0, 36.3], [-5.6, 35.94], [-6.8, 36.4]] }),
      w(1476, -9.14, 38.72,
        ['里斯本', '船难后流落葡萄牙，从事航海与制图', '哥伦布投奔里斯本的热那亚侨民，与弟弟巴尔托洛梅奥一同绘制、贩卖海图。此后数年他随葡萄牙船只北至英格兰、爱尔兰，南到几内亚海岸，并娶了圣港岛首任领主之女菲莉帕，逐渐形成向西航行前往亚洲的设想。'],
        ['Lisbon', 'Settles in Portugal as a seaman and chart-maker', 'Columbus joined the Genoese community in Lisbon and worked with his brother Bartholomew drawing and selling charts. Over the next years he sailed on Portuguese ships north to England and Ireland and south to the Guinea coast, married Filipa, daughter of the first governor of Porto Santo, and formed his plan of reaching Asia by sailing west.']),
      w(1485, -6.926, 37.208,
        ['拉比达修道院（西班牙帕洛斯附近）', '计划遭葡王否决，携子转赴西班牙', '约1484年，葡萄牙国王若昂二世的专家认为哥伦布大大低估了西航的距离，否决了他的计划。妻子去世后，他于1485年带着幼子迭戈来到帕洛斯附近的拉比达修道院，这里的方济各会士后来帮他打通了通往王室的门路。'],
        ['La Rábida Friary (near Palos, Spain)', 'Rejected in Portugal, moves to Spain with his son', "Around 1484 the experts of King John II of Portugal rejected Columbus's plan, judging that he had badly underestimated the distance to Asia. After his wife's death he came in 1485 with his young son Diego to the Franciscan friary of La Rábida near Palos, whose friars later helped him gain a hearing at court."],
        { sea: true, via: [[-9.6, 38.5], [-9.3, 36.85], [-7.3, 36.9]], wiki: { zh: '拉比达修道院', en: 'La Rábida Friary' } }),
      w(1492, -3.72, 37.19,
        ['圣菲（格拉纳达城外）', '与西班牙双王签订《圣菲协定》', '哥伦布在卡斯蒂利亚宫廷奔走六年多，计划两度被专家委员会否定。1492年1月格拉纳达陷落后，伊莎贝拉女王终于同意资助。4月17日双方在围城大营圣菲签约，许给他“大洋海军上将”和新发现土地总督的头衔，以及十分之一的收益。'],
        ['Santa Fe (outside Granada)', 'Signs the Capitulations of Santa Fe', 'Columbus spent more than six years lobbying the Castilian court, and royal commissions twice turned his plan down. After Granada fell in January 1492 Queen Isabella at last agreed to back him. The agreement signed on 17 April in the siege camp of Santa Fe promised him the titles of Admiral of the Ocean Sea and viceroy, and a tenth of the profits.'],
        { wiki: { zh: '圣塔菲协定', en: 'Capitulations of Santa Fe' } }),
      w(1492, -6.89, 37.23,
        ['帕洛斯（西班牙韦尔瓦省）', '获西班牙双王资助，率三艘船西航', '1492年8月3日清晨，哥伦布率“圣玛利亚”号、“平塔”号和“尼尼亚”号从帕洛斯启航，船员约90人，多由当地船主平松兄弟招募。他带着双王致东方君主的国书，打算向西直航日本和中国。'],
        ['Palos de la Frontera (Huelva, Spain)', 'Sails west with three ships, backed by the Spanish crown', 'At dawn on 3 August 1492 Columbus left Palos with the Santa María, the Pinta and the Niña and about 90 men, many of them recruited by the local shipowning Pinzón brothers. He carried letters from the monarchs to the rulers of the East and meant to sail due west to Japan and China.'],
        { wiki: { zh: '圣玛利亚号', en: 'Santa María (ship)' } }),
      w(1492, -17.11, 28.09,
        ['戈梅拉岛（加那利群岛）', '在加那利群岛补给', '船队在加那利群岛停留约一个月，修理“平塔”号的舵，并把“尼尼亚”号的三角帆改成更适合顺风远航的横帆。9月6日船队自戈梅拉岛的圣塞瓦斯蒂安启航，借东北信风驶入未知的大洋。'],
        ['La Gomera (Canary Islands)', 'Takes on supplies in the Canary Islands', "The fleet spent about a month in the Canaries repairing the Pinta's rudder and re-rigging the Niña with square sails better suited to running before the wind. On 6 September it left San Sebastián de la Gomera and picked up the north-east trade winds into the open ocean."],
        { sea: true, via: [[-9.8, 33.0]] }),
      w(1492, -74.5, 24.05,
        ['瓜纳哈尼（一般认为即巴哈马圣萨尔瓦多岛）', '10月12日登陆，以为到达亚洲', '航行五周后，10月12日凌晨，“平塔”号的水手望见陆地。哥伦布登上一座当地泰诺人称作瓜纳哈尼的小岛，将其命名为圣萨尔瓦多，并以西班牙双王的名义宣布占有。他认定这里是亚洲的外围岛屿，称岛民为“印度人”。'],
        ['Guanahani (generally identified with San Salvador, Bahamas)', 'Lands on 12 October, believing he has reached Asia', 'After five weeks at sea a lookout on the Pinta sighted land in the early hours of 12 October. Columbus went ashore on an island its Taino inhabitants called Guanahani, named it San Salvador and claimed it for the Spanish crown. Sure that he was among the outlying islands of Asia, he called the people "Indians".'],
        { sea: true, via: [[-35.0, 27.5], [-60.0, 25.5]], event: 'columbus-1492' }),
      w(1492, -76.13, 21.11,
        ['古巴东北岸', '抵达古巴东北岸', '10月28日，哥伦布驶抵古巴东北海岸，以为这是亚洲大陆的一角，派人深入内地寻找“大汗”的都城。使者没有找到城市和黄金，却见到当地人吸食卷起的烟叶，这是欧洲人最早的烟草记录之一。'],
        ['North-east coast of Cuba', 'Reaches the north-east coast of Cuba', 'On 28 October Columbus reached the north-eastern coast of Cuba, which he took for part of the Asian mainland, and sent men inland to find the court of the Great Khan. They found neither cities nor gold, but they did see people smoking rolled leaves, one of the first European reports of tobacco.'],
        { sea: true, via: [[-75.6, 22.6]] }),
      w(1492, -72.1, 19.75,
        ['伊斯帕尼奥拉岛北岸（今海地海地角附近）', '旗舰“圣玛利亚”号搁浅，建纳维达德据点', '12月25日圣诞夜，“圣玛利亚”号在伊斯帕尼奥拉岛北岸触礁搁浅。在当地酋长瓜卡纳加里帮助下，船员用船材建起小堡“纳维达德”（意为圣诞），留下39人驻守。哥伦布次年重返时，据点已毁，留守者无一生还。'],
        ['North coast of Hispaniola (near Cap-Haïtien, Haiti)', 'Santa María wrecked; founds the post of La Navidad', 'On Christmas night the Santa María ran aground on the north coast of Hispaniola. With help from the local chief Guacanagarí the crew used her timbers to build a small fort, La Navidad, where 39 men were left behind. When Columbus returned a year later the post had been destroyed and all of them were dead.'],
        { sea: true, via: [[-74.2, 20.3]] }),
      w(1493, -6.89, 37.23,
        ['帕洛斯', '经亚速尔群岛返回西班牙', '1493年1月，哥伦布乘“尼尼亚”号返航，途中两度遭遇风暴，先在亚速尔群岛的圣玛丽亚岛停靠，又被吹入里斯本，见到了葡萄牙国王若昂二世。3月15日他回到帕洛斯，带回少量黄金、鹦鹉和几名泰诺人。'],
        ['Palos de la Frontera', 'Returns to Spain by way of the Azores', 'Columbus started home in the Niña in January 1493. Two storms forced him first into Santa Maria in the Azores and then into Lisbon, where he was received by King John II. He reached Palos on 15 March, bringing a little gold, some parrots and several Taino captives.'],
        { sea: true, via: [[-62.0, 30.0], [-40.0, 36.0], [-25.2, 36.95], [-9.4, 38.6]] }),
      w(1493, 2.18, 41.38,
        ['巴塞罗那', '在巴塞罗那向双王复命', '1493年4月，费尔南多和伊莎贝拉在巴塞罗那隆重接见哥伦布，确认了他的全部头衔。他报告“印度”见闻的书信很快被印成多种文字传遍欧洲。同年教皇亚历山大六世颁布诏书，把新发现的土地划归卡斯蒂利亚。'],
        ['Barcelona', 'Received in triumph by the monarchs', 'In April 1493 Ferdinand and Isabella received Columbus with great honour at Barcelona and confirmed all his titles. His letter describing "the Indies" was soon printed in several languages across Europe, and that year Pope Alexander VI issued bulls assigning the newly found lands to Castile.']),
      w(1493, -6.29, 36.53,
        ['加的斯', '率17艘船开始第二次远航', '1493年9月25日，哥伦布率17艘船、1200多人自加的斯出发，船上载着马匹、牲畜、种子和工具。这一次的目的不再是探路，而是在伊斯帕尼奥拉岛建立永久殖民地。船队途中先后经过多米尼克、瓜德罗普和波多黎各。'],
        ['Cádiz', 'Sails on his second voyage with seventeen ships', 'On 25 September 1493 Columbus left Cádiz with seventeen ships and more than 1,200 men, carrying horses, livestock, seed and tools. The aim was no longer exploration but a permanent colony on Hispaniola. On the way the fleet touched at Dominica, Guadeloupe and Puerto Rico.']),
      w(1493, -71.07, 19.88,
        ['伊莎贝拉城（今多米尼加共和国北岸）', '第二次远航，建立伊莎贝拉城', '发现纳维达德据点被毁后，哥伦布向东另择地点，在1493年与1494年之交建立伊莎贝拉城。殖民者苦于饥饿与疾病，四处搜求黄金。1494年他出海探察古巴南岸和牙买加；1495年起对泰诺人武力镇压，并强征黄金贡赋。'],
        ['La Isabela (north coast of the Dominican Republic)', 'Founds La Isabela on his second voyage', 'Finding La Navidad destroyed, Columbus chose a site further east and founded La Isabela at the turn of 1493-94. The settlers suffered from hunger and disease and scoured the island for gold. In 1494 he explored southern Cuba and Jamaica, and from 1495 he put down Taino resistance by force and imposed a tribute in gold.'],
        { sea: true, via: [[-17.0, 28.0], [-40.0, 20.0], [-61.3, 15.4]], wiki: { zh: '拉伊莎贝拉', en: 'La Isabela' } }),
      w(1496, -6.29, 36.53,
        ['加的斯', '返回西班牙', '对殖民地的种种怨言传回宫廷，哥伦布留下弟弟巴尔托洛梅奥主持岛上事务，于1496年3月启程，6月抵达加的斯。他身穿方济各会士般的粗布衣晋见双王，仍获信任，但筹备下一次远航花了近两年。'],
        ['Cádiz', 'Returns to Spain', 'With complaints about the colony reaching the court, Columbus left his brother Bartholomew in charge and sailed in March 1496, arriving at Cádiz in June. He appeared before the monarchs dressed in the plain habit of a Franciscan and kept their favour, but it took nearly two years to fit out another voyage.'],
        { sea: true, via: [[-62.0, 26.0], [-30.0, 36.0]] }),
      w(1498, -61.25, 10.4,
        ['特立尼达岛', '第三次远航，首次抵达南美大陆沿岸', '1498年5月哥伦布率6艘船出发，自己带其中3艘取道佛得角群岛走偏南的航线，7月31日望见一座有三座山峰的岛，命名为特立尼达。8月初他的部下在今委内瑞拉的帕里亚半岛登岸；奥里诺科河涌出的大量淡水让他推想，这是一片极大的陆地。'],
        ['Trinidad', 'Third voyage: first reaches the South American mainland', 'Columbus sailed in May 1498 with six ships, taking three of them on a more southerly route by the Cape Verde Islands. On 31 July he sighted an island with three peaks and named it Trinidad. In early August his men landed on the Paria Peninsula of Venezuela, and the fresh water pouring from the Orinoco convinced him this was a very large land.'],
        { sea: true, via: [[-17.0, 28.0], [-24.0, 15.0], [-50.0, 9.5]] }),
      w(1498, -69.9, 18.47,
        ['圣多明各', '抵达殖民地，当地陷入动乱', '8月底哥伦布抵达其弟新建的首府圣多明各，发现以罗尔丹为首的一批殖民者已经反叛。他只得让步，把土地连同其上的泰诺人分配给殖民者役使。对哥伦布兄弟施政的控告不断传回西班牙。'],
        ['Santo Domingo', 'Finds the colony in revolt', 'At the end of August Columbus reached Santo Domingo, the new capital founded by his brother, to find a faction of settlers under Francisco Roldán in open revolt. He bought peace by granting the rebels land together with the labour of the Taino living on it. Complaints about the rule of the Columbus brothers kept reaching Spain.'],
        { sea: true, via: [[-66.0, 13.5]] }),
      w(1500, -6.29, 36.53,
        ['加的斯', '被戴上镣铐押解回西班牙', '1500年8月，双王派来的钦差博瓦迪利亚抵达圣多明各，逮捕哥伦布三兄弟，10月将他们戴着镣铐押回西班牙。双王下令释放并在格拉纳达接见了他，恢复其财产，却不再让他担任总督。'],
        ['Cádiz', 'Sent back to Spain in chains', 'In August 1500 the royal commissioner Francisco de Bobadilla arrived at Santo Domingo, arrested Columbus and his two brothers and shipped them home in irons that October. The monarchs ordered him freed and received him at Granada, restoring his property but not his office as governor.'],
        { sea: true, via: [[-62.0, 25.0], [-30.0, 35.0]] }),
      w(1502, -85.9, 16.47,
        ['瓜纳哈岛（洪都拉斯海湾群岛）', '第四次远航，考察中美洲海岸', '1502年5月，哥伦布带着13岁的儿子费尔南多，率4艘船从加的斯出发，想找到通往印度洋的海峡。7月底他在洪都拉斯外海的瓜纳哈岛遇到一艘满载棉布、可可豆和铜器的大型独木舟，这是欧洲人与玛雅商旅的首次接触。'],
        ['Guanaja (Bay Islands, Honduras)', 'Fourth voyage: explores the coast of Central America', 'Columbus left Cádiz in May 1502 with four ships and his thirteen-year-old son Ferdinand, hoping to find a strait leading to the Indian Ocean. Off Guanaja at the end of July he met a large trading canoe laden with cotton cloth, cacao beans and copper goods, the first European encounter with Maya commerce.'],
        { sea: true, via: [[-17.0, 28.0], [-40.0, 16.0], [-61.0, 14.5], [-75.0, 16.8]] }),
      w(1503, -80.87, 8.89,
        ['贝伦河口（今巴拿马加勒比海岸）', '在巴拿马海岸建据点失败', '船队顶着逆风沿洪都拉斯、尼加拉瓜、哥斯达黎加海岸南下，在巴拿马的贝拉瓜一带发现黄金。1503年初哥伦布在贝伦河口建立据点，遭当地人围攻，4月被迫放弃。此时船身已被船蛆蛀得千疮百孔。'],
        ['Mouth of the Río Belén (Caribbean coast of Panama)', 'Fails to plant a settlement in Panama', 'Beating against headwinds, the ships worked down the coasts of Honduras, Nicaragua and Costa Rica and found gold in Veragua, in present-day Panama. Early in 1503 Columbus began a settlement at the mouth of the Río Belén, but attacks by the local people forced him to abandon it in April. By then shipworm had riddled his hulls.'],
        { sea: true, via: [[-82.9, 15.6], [-82.6, 12.0], [-82.4, 10.0]] }),
      w(1503, -77.2, 18.44,
        ['圣安湾（牙买加北岸）', '困守牙买加一年', '1503年6月，仅剩的两艘船再也无法航行，哥伦布只得在牙买加北岸冲滩搁浅。两名部下乘独木舟划往伊斯帕尼奥拉求援，救援船却迟迟不来。据其子记述，他借历书预知1504年2月29日的月食，以此震慑岛民继续供应食物。'],
        ["St Ann's Bay (north coast of Jamaica)", 'Marooned on Jamaica for a year', "In June 1503 Columbus ran his last two ships, no longer seaworthy, aground on the north coast of Jamaica. Two officers crossed to Hispaniola by canoe to fetch help, which was slow to come. According to his son, he used an almanac's prediction of the lunar eclipse of 29 February 1504 to frighten the islanders into continuing to supply food."],
        { sea: true, via: [[-80.3, 9.7], [-78.6, 10.0], [-78.7, 17.5], [-78.6, 18.4], [-77.8, 18.62]] }),
      w(1504, -6.35, 36.78,
        ['桑卢卡尔-德巴拉梅达', '在牙买加困守一年后返回西班牙', '1504年6月救援船终于到来，哥伦布一行经圣多明各换船，11月7日回到西班牙的桑卢卡尔，结束了最后一次远航。他已为痛风和关节病所困；不到三周后，一直支持他的伊莎贝拉女王去世。'],
        ['Sanlúcar de Barrameda', 'Returns to Spain after a year stranded on Jamaica', 'A rescue ship finally arrived in June 1504. After changing ships at Santo Domingo, Columbus reached Sanlúcar on 7 November, ending his last voyage. He was by now crippled by gout and arthritis, and less than three weeks later his patron Queen Isabella died.'],
        { sea: true, via: [[-78.0, 18.0], [-65.0, 25.0], [-30.0, 36.0]] }),
      w(1506, -4.72, 41.65,
        ['巴利亚多利德', '在失意中病逝', '晚年的哥伦布并不贫困，却一再上书要求恢复总督职权和约定的收益，费尔南多国王始终没有答应。1506年5月20日他在巴利亚多利德去世，至死相信自己到过的是亚洲东缘。遗骨后来迁葬塞维利亚和圣多明各。'],
        ['Valladolid', 'Dies a disappointed man', 'Columbus was not poor in his last years, but he petitioned again and again for the restoration of his governorship and his promised share of the revenues, which King Ferdinand never granted. He died at Valladolid on 20 May 1506, still convinced he had reached the eastern edge of Asia. His remains were later moved to Seville and Santo Domingo.']),
    ],
    wiki: { zh: '克里斯托弗·哥伦布', en: 'Christopher Columbus' },
  },
  {
    id: 'da-vinci',
    name: { zh: '达·芬奇', en: 'Leonardo da Vinci' },
    birth: 1452, death: 1519,
    title: { zh: '艺术家、发明家', en: 'Artist and inventor' },
    region: 'europe',
    sprite: 'scroll',
    summary: {
      zh: '意大利文艺复兴时期的艺术巨匠与博学者。他生于托斯卡纳，先后在佛罗伦萨、米兰、罗马为各方权贵效力，晚年应邀赴法国。《最后的晚餐》《蒙娜丽莎》是西方绘画史上的经典；他还在解剖学、光学、水利、机械与飞行器设计等领域留下七千余页手稿，被视为“文艺复兴人”的典范。',
      en: 'Italian painter, engineer and polymath of the High Renaissance. Trained in Florence, he worked for patrons in Milan, Florence and Rome and spent his last years in France. The Last Supper and the Mona Lisa are among the most famous paintings in Western art, and his notebooks, of which more than 7,000 pages survive, range over anatomy, optics, hydraulics, mechanics and flying machines. He is often regarded as the model of the "Renaissance man".',
    },
    route: [
      w(1452, 10.93, 43.79,
        ['芬奇镇（今意大利托斯卡纳大区）', '生于佛罗伦萨附近的芬奇镇', '1452年4月15日，列奥纳多生于芬奇镇，相传是在附近的安基亚诺村，是公证人皮耶罗与农家女卡泰丽娜的非婚生子。他在祖父家长大，只受过基础的读写和算术教育，没有系统学过拉丁文。'],
        ['Vinci (Tuscany, Italy)', 'Born at Vinci, near Florence', "Leonardo was born on 15 April 1452 at Vinci, by tradition in the nearby hamlet of Anchiano, the illegitimate son of the notary Ser Piero and a peasant woman named Caterina. Raised in his grandfather's household, he had only a basic schooling in reading, writing and arithmetic and never properly learned Latin."]),
      w(1466, 11.26, 43.77,
        ['佛罗伦萨', '入韦罗基奥画室学艺', '约在1466年前后，少年列奥纳多随父亲来到佛罗伦萨，进入雕塑家、画家韦罗基奥的作坊当学徒。这间作坊承接绘画、雕塑和金工等各类订件，他在此学习素描、调色、铸铜和机械，前后约十年。'],
        ['Florence', "Apprenticed in Verrocchio's workshop", 'Around 1466 the young Leonardo moved to Florence with his father and was apprenticed to the sculptor and painter Andrea del Verrocchio. The workshop took commissions in painting, sculpture and metalwork, and there he learned drawing, the preparation of colours, bronze casting and mechanics over roughly a decade.']),
      w(1472, 11.26, 43.77,
        ['佛罗伦萨', '加入画家行会，成为独立画师', '1472年，20岁的列奥纳多已列名佛罗伦萨画家行会圣路加公会。他在韦罗基奥的《基督受洗》中画了一位天使，并创作了《天使报喜》。1481年他受托为一座修道院绘制《三博士来朝》，尚未完成便离开了佛罗伦萨。'],
        ['Florence', "Enrolled as a master in the painters' guild", "By 1472 the twenty-year-old Leonardo was listed as a member of the Company of St Luke, the painters' guild of Florence. He painted an angel in Verrocchio's Baptism of Christ and his own Annunciation. In 1481 a monastery commissioned the Adoration of the Magi from him, which he left unfinished when he moved away."],
        { wiki: { zh: '天使报喜 (达芬奇)', en: 'Annunciation (Leonardo)' } }),
      w(1482, 9.19, 45.46,
        ['米兰', '前往米兰，为斯福尔扎宫廷效力', '约1482年，列奥纳多来到米兰投奔当权者卢多维科·斯福尔扎。在一封自荐信的草稿中，他列举自己设计桥梁、火炮和攻城器械的本领，绘画只在末尾一笔带过。此后十七年他在宫廷任画师和工程师，绘有《岩间圣母》，并筹划一尊巨型青铜骑马像。'],
        ['Milan', 'Moves to Milan to serve the Sforza court', 'About 1482 Leonardo moved to Milan and entered the service of its ruler, Ludovico Sforza. A draft letter of introduction lists his skills in designing bridges, cannon and siege engines and mentions painting only at the end. In seventeen years there as court painter and engineer he painted the Virgin of the Rocks and planned a colossal bronze horse.'],
        { wiki: { zh: '岩间圣母', en: 'Virgin of the Rocks' } }),
      w(1495, 9.171, 45.466,
        ['米兰（圣玛利亚感恩教堂）', '绘制《最后的晚餐》', '约1495年至1498年，列奥纳多在圣玛利亚感恩教堂修道院的餐厅墙上绘制《最后的晚餐》，捕捉耶稣说出“你们中间有一个人要出卖我”时十二门徒的反应。他没有采用传统的湿壁画技法，而是在干墙上用蛋彩和油彩试验，画面不久便开始剥落。'],
        ['Milan (Santa Maria delle Grazie)', 'Paints The Last Supper', 'Between about 1495 and 1498 Leonardo painted The Last Supper on the refectory wall of the convent of Santa Maria delle Grazie, showing the apostles reacting as Christ announces that one of them will betray him. Instead of true fresco he experimented with tempera and oil on dry plaster, and the paint soon began to flake.'],
        { wiki: { zh: '最后的晚餐 (达芬奇)', en: 'The Last Supper (Leonardo)' } }),
      w(1500, 10.79, 45.16,
        ['曼托瓦', '离开米兰，途经曼托瓦', '1499年法军攻占米兰，斯福尔扎倒台，列奥纳多为骑马像制作的黏土模型成了法国弓手的箭靶。年底他与数学家卢卡·帕乔利一同离开，途经曼托瓦时为侯爵夫人伊莎贝拉·德斯特画了一幅素描肖像，这幅画稿今藏卢浮宫。'],
        ['Mantua', 'Leaves Milan and stops at Mantua', "The French took Milan in 1499 and the Sforza fell; the clay model for Leonardo's great horse ended up as a target for French archers. He left at the end of the year with the mathematician Luca Pacioli and stopped at Mantua, where he drew a portrait of the marchioness Isabella d'Este that is now in the Louvre."]),
      w(1500, 12.34, 45.44,
        ['威尼斯', '辗转威尼斯，为共和国筹划防务', '1500年3月列奥纳多到达威尼斯。当时奥斯曼军队正威胁威尼斯的东北边境，他受托考察伊松佐河一线的防御，提出筑坝放水阻敌的方案，笔记中还留下了潜水装备的设想。不久他返回阔别十八年的佛罗伦萨。'],
        ['Venice', 'In Venice, advises the republic on its defences', "Leonardo reached Venice in March 1500. With Ottoman forces threatening the republic's north-eastern frontier, he was consulted on defences along the Isonzo river and proposed a movable dam to flood the valley; his notes also sketch equipment for divers. Soon afterwards he returned to Florence after eighteen years away."]),
      w(1502, 11.71, 44.35,
        ['伊莫拉', '任切萨雷·波吉亚的军事工程师', '1502年夏，教皇亚历山大六世之子切萨雷·波吉亚聘列奥纳多为建筑师和总工程师，凭一纸通行文书巡视罗马涅各地的城防。他到过乌尔比诺、切塞纳、切塞纳蒂科等地，并在伊莫拉绘出一幅精确的垂直俯视城市平面图，是制图史上的名作。'],
        ['Imola', 'Military engineer to Cesare Borgia', 'In summer 1502 Cesare Borgia, the son of Pope Alexander VI, engaged Leonardo as his architect and general engineer, with a pass to inspect fortresses across the Romagna. He visited Urbino, Cesena and Cesenatico, and at Imola he drew a measured town plan seen from directly above, a landmark in the history of map-making.']),
      w(1503, 11.26, 43.77,
        ['佛罗伦萨', '开始创作《蒙娜丽莎》', '约1503年，列奥纳多开始为丝绸商人焦孔多之妻丽莎画像，此画他一直带在身边修改，终生未交付。同年佛罗伦萨共和国委托他在市政厅绘制壁画《安吉亚里之战》，对面的墙面交给米开朗琪罗；两幅壁画最终都没有完成。'],
        ['Florence', 'Begins the Mona Lisa', 'Around 1503 Leonardo began a portrait of Lisa, wife of the silk merchant Francesco del Giocondo; he kept it with him and went on retouching it for years, never delivering it. The same year the Florentine republic commissioned him to paint the Battle of Anghiari in the Palazzo Vecchio, opposite a wall assigned to Michelangelo. Neither mural was completed.'],
        { wiki: { zh: '蒙娜丽莎', en: 'Mona Lisa' } }),
      w(1506, 9.19, 45.46,
        ['米兰', '应法国总督之召重返米兰', '1506年，统治米兰的法国总督夏尔·德·昂布瓦斯把列奥纳多从佛罗伦萨请回，他从1508年起在此长住。这一时期他绘制《圣母子与圣安妮》，研究水利与地质，并与帕维亚的一位解剖学教授合作，画下大量人体解剖图。'],
        ['Milan', 'Called back to Milan by its French governor', "In 1506 Charles d'Amboise, the French governor of Milan, summoned Leonardo back from Florence, and from 1508 he lived there again. In these years he worked on the Virgin and Child with St Anne, studied hydraulics and geology, and made many of his anatomical drawings, some in collaboration with a professor of anatomy at Pavia."]),
      w(1513, 12.48, 41.9,
        ['罗马', '寓居梵蒂冈', '1513年法国人被逐出米兰，列奥纳多南下罗马，托庇于教皇利奥十世之弟朱利亚诺·德·美第奇，住在梵蒂冈的观景楼。当时拉斐尔和米开朗琪罗正在罗马大展身手，年过六旬的他却少有重要委托，主要研究镜面、几何和植物。'],
        ['Rome', 'Lives in the Vatican', "When the French were driven from Milan in 1513, Leonardo went to Rome under the protection of Giuliano de' Medici, brother of Pope Leo X, and was lodged in the Belvedere of the Vatican. While Raphael and Michelangelo flourished there, he received few major commissions and occupied himself with mirrors, geometry and botany."]),
      w(1516, 0.98, 47.41,
        ['昂布瓦斯', '应法王弗朗索瓦一世之邀定居法国', '1516年，64岁的列奥纳多带着弟子梅尔齐翻越阿尔卑斯山来到法国，随身携带《蒙娜丽莎》等画作。弗朗索瓦一世授予他“国王首席画家、工程师和建筑师”的名号和丰厚年金，把王宫旁的克洛吕斯庄园拨给他居住。'],
        ['Amboise', 'Settles in France at the invitation of Francis I', 'In 1516 the 64-year-old Leonardo crossed the Alps to France with his pupil Francesco Melzi, bringing the Mona Lisa and other paintings with him. Francis I named him first painter, engineer and architect to the king, granted him a generous pension and gave him the manor of Clos Lucé, close to the royal château.'],
        { wiki: { zh: '克洛·吕斯城堡', en: 'Clos Lucé' } }),
      w(1517, 1.745, 47.36,
        ['罗莫朗坦', '为法王规划罗莫朗坦新城', '约1517年，列奥纳多前往索洛涅地区的罗莫朗坦考察，为国王设计一座新王宫和配有运河网的理想城市，工程动工不久即告中止。此时他右手已经麻痹，仍继续整理笔记，并为宫廷庆典设计机关和布景。'],
        ['Romorantin', 'Plans a new royal town at Romorantin', 'Around 1517 Leonardo travelled to Romorantin in the Sologne, where he drew up plans for a new royal palace and an ideal town served by a network of canals. Work stopped soon after it began. His right hand was by now paralysed, but he went on ordering his notes and devising machinery for court festivities.']),
      w(1519, 0.98, 47.41,
        ['昂布瓦斯（克洛吕斯庄园）', '病逝于克洛吕斯城堡', '1519年5月2日，列奥纳多在克洛吕斯去世，享年67岁，葬于昂布瓦斯城堡内的教堂。瓦萨里称他死在弗朗索瓦一世怀中，这只是传说。他把全部手稿和画具留给梅尔齐，这些笔记后来散落各地。'],
        ['Amboise (Clos Lucé)', 'Dies at Clos Lucé', "Leonardo died at Clos Lucé on 2 May 1519, aged 67, and was buried in a church within the Château d'Amboise. Vasari's story that he died in the arms of Francis I is a legend. He left his manuscripts and drawings to Melzi; the notebooks were later scattered across many collections."],
        { wiki: { zh: '昂布瓦斯城堡', en: "Château d'Amboise" } }),
    ],
    wiki: { zh: '列奥纳多·达·芬奇', en: 'Leonardo da Vinci' },
  },
  {
    id: 'magellan',
    name: { zh: '麦哲伦', en: 'Ferdinand Magellan' },
    birth: 1480, death: 1521, approx: true,
    title: { zh: '航海家', en: 'Navigator' },
    region: 'europe',
    lineage: 'spain',
    sprite: 'ship',
    summary: {
      zh: '葡萄牙籍航海家。1519年受西班牙国王资助，率船队西航寻找通往香料群岛的航路，穿越南美洲南端的海峡进入太平洋并为其命名。1521年在菲律宾麦克坦岛战死。船队余部在埃尔卡诺率领下于1522年返回西班牙，完成人类首次环球航行，也揭示了太平洋的辽阔。',
      en: 'Portuguese-born navigator in the service of Spain. In 1519 he sailed west with five ships to find a route to the Spice Islands, passed through the strait at the tip of South America that now bears his name, and crossed and named the Pacific Ocean. He was killed on Mactan in the Philippines in 1521. The survivors, led by Juan Sebastián Elcano, reached Spain in 1522, completing the first circumnavigation of the globe and revealing the true extent of the Pacific.',
    },
    route: [
      w(1480, -7.575, 41.265,
        ['萨布罗萨（葡萄牙北部，传统说法）', '生于葡萄牙北部的小贵族家庭', '麦哲伦约于1480年出生，葡萄牙语名费尔南·德·麦加良斯。出生地传统上认为是北部山区的萨布罗萨，也有波尔图等说法。他出身小贵族，父母早逝，少年时被送到里斯本宫廷当侍童，在那里学习航海和制图知识。'],
        ['Sabrosa (northern Portugal, by tradition)', 'Born into the minor nobility of northern Portugal', 'Magellan, in Portuguese Fernão de Magalhães, was born about 1480. Tradition places his birth at Sabrosa in the northern hills, though Porto has also been proposed. A member of the minor nobility, he lost his parents young and was sent as a page to the royal court in Lisbon, where he learned navigation and cartography.']),
      w(1505, -9.14, 38.72,
        ['里斯本', '随葡萄牙舰队前往印度', '1505年3月，约25岁的麦哲伦加入首任印度总督阿尔梅达的舰队，绕好望角前往东方。此后八年他辗转东非、印度和马来半岛，1506年在坎纳诺尔海战中负伤，1509年参加了确立葡萄牙印度洋霸权的第乌海战。'],
        ['Lisbon', 'Sails for India with the Portuguese fleet', 'In March 1505 Magellan, aged about 25, joined the fleet of Francisco de Almeida, the first Portuguese viceroy of India, and sailed round the Cape of Good Hope. He spent the next eight years in East Africa, India and Malaya, was wounded at the battle of Cannanore in 1506 and fought at Diu in 1509.']),
      w(1511, 102.25, 2.2,
        ['马六甲', '参与葡萄牙攻占马六甲', '1509年麦哲伦曾随第一支葡萄牙船队到过马六甲。1511年8月，他在阿尔布克尔克麾下参与攻占这座控扼海峡的商港。他在此得到一名马来奴仆恩里克，日后随他远航充当通译；好友塞朗则继续东行，从香料群岛给他寄来书信。'],
        ['Malacca', 'Takes part in the Portuguese capture of Malacca', 'Magellan had first seen Malacca with a Portuguese squadron in 1509. In August 1511 he served under Afonso de Albuquerque when the great trading port on the strait was stormed. There he acquired a Malay servant, Enrique, later his interpreter, while his friend Francisco Serrão sailed on to the Spice Islands and wrote to him from there.'],
        { sea: true, via: [[-18.0, 15.0], [0.0, -20.0], [20.0, -37.0], [40.7, -15.0], [60.0, 2.0], [80.0, 5.6], [95.0, 6.0]], wiki: { zh: '法摩沙堡', en: 'A Famosa' } }),
      w(1517, -5.99, 37.39,
        ['塞维利亚', '不受葡萄牙重用，转投西班牙', '麦哲伦1513年回到葡萄牙，随后在摩洛哥作战时膝部受伤，落下跛足。国王曼努埃尔一世拒绝为他增加年金，也不支持他西航香料群岛的设想。1517年10月他来到塞维利亚，娶旅居当地的葡萄牙人巴尔博萨之女为妻，转而向西班牙王室献策。'],
        ['Seville', 'Passed over in Portugal, turns to Spain', 'Magellan returned to Portugal in 1513 and was lamed by a knee wound while fighting in Morocco. King Manuel I refused him a larger pension and showed no interest in his idea of reaching the Spice Islands by the west. In October 1517 he moved to Seville, married the daughter of a Portuguese settler there and offered his plan to Spain.'],
        { sea: true, via: [[80.0, 5.6], [55.0, -10.0], [20.0, -37.0], [-5.0, -10.0], [-20.0, 20.0]] }),
      w(1518, -4.72, 41.65,
        ['巴利亚多利德', '与西班牙国王签订远航协定', '1518年3月，麦哲伦与宇宙学家法莱罗在巴利亚多利德觐见年轻的国王卡洛斯一世，主张香料群岛位于《托德西利亚斯条约》划给西班牙的半球之内。3月22日双方签约，国王出资装备5艘船，许给二人新发现土地的总督头衔和部分收益。'],
        ['Valladolid', 'Wins a contract from the king of Spain', 'In March 1518 Magellan and the cosmographer Rui Faleiro were received at Valladolid by the young King Charles I. They argued that the Spice Islands lay in the half of the world assigned to Spain by the Treaty of Tordesillas. A contract signed on 22 March promised five ships, the governorship of lands discovered and a share of the profits.']),
      w(1519, -5.99, 37.39,
        ['塞维利亚', '船队自塞维利亚启程', '船队在塞维利亚筹备了一年多，葡萄牙方面多方阻挠，西班牙船长们对这位葡萄牙籍统帅也心怀不满。1519年8月10日，旗舰“特立尼达”号等5艘船离开塞维利亚码头，沿瓜达尔基维尔河下行至河口的桑卢卡尔，在那里做最后的补给。'],
        ['Seville', 'The fleet sets out from Seville', 'The fleet took more than a year to fit out at Seville, hampered by Portuguese agents and by the resentment of Spanish captains at serving under a Portuguese commander. On 10 August 1519 the flagship Trinidad and four other ships left the quays of Seville and dropped down the Guadalquivir to Sanlúcar for final provisioning.']),
      w(1519, -6.35, 36.78,
        ['桑卢卡尔-德巴拉梅达', '9月率五艘船、约270人出发', '1519年9月20日，船队驶出桑卢卡尔进入大西洋。船员来自西班牙、葡萄牙、意大利、希腊、法国等地，其中有来自威尼斯共和国的皮加费塔，他留下的航海日记是这次远航最重要的记录。船队先到加那利群岛，再沿非洲西岸南下，然后横渡大西洋。'],
        ['Sanlúcar de Barrameda', 'Sails in September with five ships and about 270 men', 'On 20 September 1519 the fleet left Sanlúcar for the open Atlantic. The crews came from Spain, Portugal, Italy, Greece, France and beyond; among them was Antonio Pigafetta, from the Republic of Venice, whose journal is the principal record of the voyage. The ships called at the Canaries, ran down the African coast and then crossed the ocean.'],
        { event: 'magellan-circumnavigation' }),
      w(1519, -43.17, -22.9,
        ['里约热内卢湾（巴西）', '抵达巴西', '12月13日，船队驶入瓜纳巴拉湾，即今里约热内卢所在地，停留约两周补充淡水和食物，用小刀、铃铛等小物件向当地图皮人换取给养。随后船队沿海岸南下，逐一探查包括拉普拉塔河口在内的每一处海湾，寻找通往西方的海峡。'],
        ['Bay of Rio de Janeiro (Brazil)', 'Reaches Brazil', 'On 13 December the fleet entered Guanabara Bay, the site of present-day Rio de Janeiro, and stayed about two weeks taking on water and trading knives and bells with the Tupi for food. It then followed the coast southward, probing every inlet, including the wide estuary of the Río de la Plata, for a passage to the west.'],
        { sea: true, via: [[-16.5, 28.3], [-22.0, 10.0], [-32.0, -8.0]] }),
      w(1520, -67.7, -49.3,
        ['圣胡利安港（阿根廷巴塔哥尼亚）', '在巴塔哥尼亚越冬，平定叛乱', '1520年3月底，船队在荒凉的圣胡利安港停泊过冬。复活节之夜三名西班牙船长发动叛乱，麦哲伦迅速反击，处死一人，后来又把另一名主谋放逐在岸上。越冬期间“圣地亚哥”号在探路时失事，船员们还遇到了被称作“巴塔哥尼亚人”的高大原住民。'],
        ['Puerto San Julián (Patagonia, Argentina)', 'Winters in Patagonia and puts down a mutiny', 'At the end of March 1520 the fleet anchored for the winter in the bleak harbour of San Julián. On Easter night three Spanish captains mutinied; Magellan struck back quickly, had one executed and later marooned another. During the stay the Santiago was wrecked on a scouting trip, and the crews met the tall people they called Patagonians.'],
        { sea: true, via: [[-50.0, -33.0], [-60.0, -42.0]] }),
      w(1520, -70.9, -53.2,
        ['麦哲伦海峡（智利南端）', '历时38天穿过后来以其命名的海峡', '1520年10月21日，船队在南纬52度附近发现一处海口，驶入曲折的水道。南岸夜间火光点点，因而得名“火地”。途中“圣安东尼奥”号私自掉头返回西班牙。11月28日，余下的3艘船驶出海峡，进入一片平静的大洋，麦哲伦称之为“太平洋”。'],
        ['Strait of Magellan (southern Chile)', 'Spends 38 days passing the strait later named after him', 'On 21 October 1520 the fleet found an opening near latitude 52 degrees south and entered a long, winding channel. The fires seen at night on the southern shore gave Tierra del Fuego its name. The San Antonio deserted and turned back for Spain. On 28 November the three remaining ships emerged into a calm ocean that Magellan called the Pacific.'],
        { sea: true, via: [[-68.3, -52.4]], wiki: { zh: '麦哲伦海峡', en: 'Strait of Magellan' } }),
      w(1521, 144.79, 13.44,
        ['关岛（马里亚纳群岛）', '横渡“太平洋”，船员饱受饥饿与坏血病之苦', '船队在太平洋上航行了三个多月，其间只见到两座无人荒岛。据皮加费塔记载，船员吃的是生了虫的饼干碎屑、泡软的牛皮和木屑，老鼠也成了高价货，约20人死于坏血病。1521年3月6日船队到达关岛，才得到新鲜食物。'],
        ['Guam (Mariana Islands)', 'Crosses the Pacific amid hunger and scurvy', 'The ships sailed for more than three months across the Pacific, sighting only two uninhabited islets. Pigafetta records that the men ate worm-ridden biscuit crumbs, soaked ox-hides and sawdust, and paid high prices for rats; about twenty died of scurvy. On 6 March 1521 they reached Guam and at last obtained fresh food.'],
        { sea: true, via: [[-76.0, -45.0], [-100.0, -25.0], [-140.0, -10.0], [175.0, 8.0]] }),
      w(1521, 123.9, 10.3,
        ['宿务（菲律宾）', '抵达菲律宾，为宿务首领施洗', '船队3月中旬抵达菲律宾群岛东部，在霍蒙洪岛休整，又在利马萨瓦岛举行了群岛上有记载的第一场弥撒。4月7日到达宿务后，麦哲伦与首领胡马邦结盟；一周后胡马邦夫妇和数百名岛民受洗，麦哲伦在岸上立起一座十字架。'],
        ['Cebu (Philippines)', 'Reaches the Philippines and baptises the ruler of Cebu', 'The fleet reached the eastern Philippines in mid-March, rested at Homonhon and held the first recorded Mass in the islands at Limasawa. Arriving at Cebu on 7 April, Magellan made an alliance with its ruler, Rajah Humabon. A week later Humabon, his wife and hundreds of islanders were baptised, and a large cross was set up on the shore.'],
        { sea: true, via: [[130.0, 11.5]], wiki: { zh: '麦哲伦十字架', en: "Magellan's Cross" } }),
      w(1521, 123.97, 10.31,
        ['麦克坦岛（菲律宾）', '与当地首领拉普拉普交战，阵亡', '为替胡马邦压服不肯归顺的邻岛首领拉普拉普，麦哲伦于1521年4月27日率约50人涉水登上麦克坦岛，遭到上千名战士围攻。船炮因礁盘水浅无法靠近支援，他在掩护部下撤退时被长矛和砍刀杀死，遗体未能收回。'],
        ['Mactan (Philippines)', 'Killed fighting the chief Lapulapu', 'To force the neighbouring chief Lapulapu to submit to Humabon, Magellan waded ashore on Mactan on 27 April 1521 with about fifty men and was met by well over a thousand warriors. The ships could not come close enough over the reef to support him. He was cut down with spears and blades while covering the retreat, and his body was never recovered.'],
        { wiki: { zh: '麦克坦岛战役', en: 'Battle of Mactan' } }),
      w(1521, 127.4, 0.67,
        ['蒂多雷岛（今印度尼西亚马鲁古群岛）', '船队余部抵达香料群岛', '麦哲伦死后，幸存者因人手不足烧掉一艘船，辗转巴拉望和文莱。1521年11月8日，“特立尼达”号和“维多利亚”号终于到达盛产丁香的蒂多雷岛，与当地苏丹交易，满载丁香。“特立尼达”号因漏水滞留，后被葡萄牙人俘获。'],
        ['Tidore (Maluku Islands, Indonesia)', 'The survivors reach the Spice Islands', "After Magellan's death the survivors, too few to man three ships, burned one and wandered by way of Palawan and Brunei. On 8 November 1521 the Trinidad and the Victoria finally anchored at Tidore, where they traded with the sultan and loaded cloves. The leaking Trinidad stayed behind and was later seized by the Portuguese."],
        { sea: true, via: [[123.75, 9.95], [123.5, 9.4], [123.36, 9.15], [123.3, 8.85], [122.2, 8.25], [121.8, 7.4], [121.75, 6.95], [122.05, 6.79], [122.6, 6.72], [124.0, 5.8], [125.4, 5.1], [126.05, 3.9], [126.7, 1.7], [127.05, 0.75]] }),
      w(1522, -6.35, 36.78,
        ['桑卢卡尔-德巴拉梅达', '埃尔卡诺率“维多利亚”号返航，完成首次环球航行', '巴斯克人埃尔卡诺指挥“维多利亚”号于1521年12月离开蒂多雷，为避开葡萄牙人，远离海岸横渡印度洋、绕过好望角。1522年9月6日船回到桑卢卡尔时，船上只剩18名当初出发的欧洲船员，所载丁香的价值却足以抵偿整个船队的花费。'],
        ['Sanlúcar de Barrameda', 'Elcano brings the Victoria home, completing the circumnavigation', 'The Basque Juan Sebastián Elcano took the Victoria out of Tidore in December 1521 and, to avoid the Portuguese, crossed the Indian Ocean far from land and rounded the Cape of Good Hope. When she reached Sanlúcar on 6 September 1522 only 18 of the Europeans who had set out were aboard, yet her cloves more than paid for the fleet.'],
        { sea: true, via: [[127.4, 0.7], [120.0, -9.0], [100.0, -20.0], [60.0, -38.0], [20.0, -36.0], [-5.0, -15.0], [-24.0, 15.0], [-18.0, 30.0]], wiki: { zh: '维多利亚号', en: 'Victoria (ship)' } }),
    ],
    wiki: { zh: '斐迪南·麦哲伦', en: 'Ferdinand Magellan' },
  },
  {
    id: 'martin-luther',
    name: { zh: '马丁·路德', en: 'Martin Luther' },
    birth: 1483, death: 1546,
    title: { zh: '宗教改革家', en: 'Theologian and reformer' },
    region: 'europe',
    lineage: 'germany',
    sprite: 'scroll',
    summary: {
      zh: '德意志神学家，宗教改革的发起者。1517年发表《九十五条论纲》抨击赎罪券，提出“因信称义”，否认教皇的至高权威。他将《圣经》译为德文，对德语的规范化影响深远。路德的改革引发了新教运动，彻底改变了欧洲的宗教与政治格局。',
      en: 'German theologian who set off the Protestant Reformation. In 1517 he issued the Ninety-five Theses against the sale of indulgences; he went on to teach justification by faith alone and to reject the supreme authority of the pope. His German translation of the Bible did much to shape the standard written language. The movement he began split Western Christianity and transformed the religious and political order of Europe.',
    },
    route: [
      w(1483, 11.55, 51.53,
        ['艾斯莱本（今德国萨克森-安哈尔特州）', '生于曼斯费尔德伯国的艾斯莱本', '1483年11月10日，路德生于艾斯莱本，次日即圣马丁节受洗，因而取名马丁。父亲汉斯·路德出身农家，以采矿、炼铜为业。路德出生后不久，全家便迁往附近的矿业城镇曼斯费尔德。'],
        ['Eisleben (Saxony-Anhalt, Germany)', 'Born at Eisleben in the County of Mansfeld', "Luther was born at Eisleben on 10 November 1483 and baptised the next day, the feast of St Martin, whose name he was given. His father, Hans Luder, came from farming stock and made his living in copper mining and smelting. Soon after Martin's birth the family moved to the nearby mining town of Mansfeld."]),
      w(1484, 11.45, 51.59,
        ['曼斯费尔德', '在矿业城镇曼斯费尔德长大', '路德一家1484年迁居曼斯费尔德。父亲从矿工做起，后来租下几处铜矿和冶炼炉，并被推为市民代表参与市政。路德在当地的拉丁文学校开蒙，管教严厉；父亲一心盼他日后成为律师。'],
        ['Mansfeld', 'Grows up in the mining town of Mansfeld', 'The family moved to Mansfeld in 1484. Hans Luder worked his way up from miner to leaseholder of several copper mines and smelters and represented his fellow citizens on the town council. Martin began his schooling at the local Latin school under strict discipline; his father hoped to see him become a lawyer.']),
      w(1498, 10.32, 50.975,
        ['艾森纳赫', '在艾森纳赫上学', '路德十三四岁时先到马格德堡读了一年书，1498年转到母亲家族所在的艾森纳赫，就读圣乔治教区学校。他曾和同学一起沿街唱歌换取面包，后来寄住在殷实的市民家中。1501年，他进入爱尔福特大学。'],
        ['Eisenach', 'Attends school at Eisenach', "After a year at school in Magdeburg, the young Luther moved in 1498 to Eisenach, where his mother's family lived, and attended the parish school of St George. Like other pupils he sang in the streets for bread, and he later boarded with a well-to-do local family. In 1501 he went on to the University of Erfurt."]),
      w(1505, 11.03, 50.98,
        ['爱尔福特', '进入奥古斯丁修会', '路德1505年初在爱尔福特大学获文科硕士学位，遵父命改习法律。7月2日他在城外的施托特恩海姆遇雷暴，惊恐中向圣安娜许愿出家。两周后他不顾父亲反对进入奥古斯丁隐修院，1507年晋铎为神父。'],
        ['Erfurt', 'Enters the Augustinian order', "Luther took his master's degree at the University of Erfurt early in 1505 and began to study law as his father wished. Caught in a thunderstorm near Stotternheim on 2 July, he vowed to St Anne that he would become a monk. Two weeks later, against his father's wishes, he entered the Augustinian friary; he was ordained priest in 1507."],
        { wiki: { zh: '爱尔福特奥古斯丁修道院', en: "St. Augustine's Monastery (Erfurt)" } }),
      w(1510, 12.48, 41.9,
        ['罗马', '赴罗马，目睹教廷的奢靡', '1510年冬，路德受修会差遣，与一名同伴徒步翻越阿尔卑斯山前往罗马办理会务，停留约四周。他虔诚地朝拜各处圣地，跪着爬上“圣阶”；罗马教士的敷衍与世俗作风却给他留下很坏的印象，多年后仍一再提起。'],
        ['Rome', 'Travels to Rome and sees the worldliness of the Curia', 'In the winter of 1510-11 Luther was sent with a fellow friar on business for his order, walking across the Alps to Rome, where he stayed about four weeks. He devoutly visited the shrines and climbed the Holy Stairs on his knees, but the carelessness and worldliness of the Roman clergy left a bad impression that he recalled in later years.']),
      w(1512, 12.65, 51.87,
        ['维滕贝格', '获神学博士学位，任维滕贝格大学教授', '1512年10月，路德在萨克森选帝侯“智者”腓特烈新办的维滕贝格大学获神学博士学位，接替导师施陶皮茨担任圣经学教授。此后几年他讲授《诗篇》《罗马书》和《加拉太书》，逐渐形成“人唯独因信称义”的见解。'],
        ['Wittenberg', 'Becomes doctor of theology and professor at Wittenberg', 'In October 1512 Luther took his doctorate in theology at the new university founded at Wittenberg by Elector Frederick the Wise of Saxony, and succeeded his mentor Johann von Staupitz as professor of the Bible. Lecturing on the Psalms, Romans and Galatians over the next years, he came to his conviction that a person is justified by faith alone.']),
      w(1517, 12.65, 51.87,
        ['维滕贝格（诸圣堂）', '发表《九十五条论纲》', '多明我会士台彻尔在邻近地区兜售赎罪券，为罗马修建圣彼得大教堂筹款。1517年10月31日，路德把《九十五条论纲》寄给美因茨大主教，相传还把它张贴在诸圣堂（城堡教堂）的大门上。论纲本为学术辩论而写，却在数周内被印刷传遍德意志。'],
        ["Wittenberg (All Saints' Church)", 'Issues the Ninety-five Theses', "The Dominican Johann Tetzel was selling indulgences nearby to help fund the rebuilding of St Peter's in Rome. On 31 October 1517 Luther sent his Ninety-five Theses to the archbishop of Mainz and, according to tradition, posted them on the door of the Castle Church. Written for academic debate, they were printed and spread across Germany within weeks."],
        { event: 'ninety-five-theses' }),
      w(1518, 8.69, 49.41,
        ['海德堡', '在海德堡辩论中阐述“十字架神学”', '1518年4月，路德步行前往海德堡，出席奥古斯丁会的例会，并于26日主持辩论。他没有再谈赎罪券，而是阐述人不能凭善功得救的“十字架神学”。在座的青年学者布策尔、布伦茨等人深受触动，后来都成了德意志西南部的改革者。'],
        ['Heidelberg', 'Sets out his "theology of the cross" at Heidelberg', 'In April 1518 Luther walked to Heidelberg for a chapter meeting of the Augustinians and presided over a disputation on the 26th. Leaving indulgences aside, he set out his "theology of the cross", arguing that no one is saved by good works. Among the young listeners were Martin Bucer and Johannes Brenz, later reformers in south-west Germany.']),
      w(1518, 10.9, 48.37,
        ['奥格斯堡', '面对教皇特使拒绝认错', '1518年10月，路德奉召到刚开过帝国会议的奥格斯堡，在富格尔家的宅邸连续三天接受教皇特使、枢机主教卡耶坦的讯问。卡耶坦要求他无条件收回主张，他则坚持要对方依据《圣经》指出错在何处。会谈破裂后，朋友们帮他连夜出城。'],
        ['Augsburg', 'Refuses to recant before the papal legate', 'In October 1518 Luther was summoned to Augsburg, where an imperial diet had just met, and was questioned over three days by the papal legate, Cardinal Cajetan, in the house of the Fugger family. Cajetan demanded an unconditional recantation; Luther insisted on being shown his error from Scripture. When the talks broke down, friends helped him slip out of the city by night.']),
      w(1519, 12.37, 51.34,
        ['莱比锡', '在莱比锡与埃克公开辩论', '1519年夏，路德在莱比锡的普莱森堡与因戈尔施塔特的神学家约翰·埃克辩论。在埃克步步紧逼之下，路德当众表示教皇的权威并非出自神授，大公会议也会犯错，百年前被判为异端烧死的胡斯有些主张是正确的。他与罗马的决裂至此难以挽回。'],
        ['Leipzig', 'Debates Johann Eck at Leipzig', 'In the summer of 1519 Luther faced the Ingolstadt theologian Johann Eck in a public disputation at the Pleissenburg in Leipzig. Pressed by Eck, he declared that papal authority was not of divine origin, that church councils could err, and that Jan Hus, burned as a heretic a century earlier, had been right on some points. The breach with Rome became hard to mend.']),
      w(1520, 12.657, 51.863,
        ['维滕贝格（埃尔斯特门外）', '当众焚毁教皇谕令', '1520年路德接连写出《致德意志基督教贵族书》《教会被掳于巴比伦》《论基督徒的自由》三篇著作，系统提出改革主张。教皇利奥十世颁布谕令，限他60天内认错；12月10日，他在埃尔斯特门外当着师生的面把谕令和教会法典投入火中，次年1月被开除教籍。'],
        ['Wittenberg (outside the Elster Gate)', 'Burns the papal bull', 'In 1520 Luther set out his programme in three tracts, among them To the Christian Nobility of the German Nation and On the Freedom of a Christian. Pope Leo X issued a bull giving him sixty days to recant. On 10 December Luther burned it, with volumes of canon law, outside the Elster Gate; he was excommunicated in January 1521.']),
      w(1521, 8.36, 49.63,
        ['沃尔姆斯', '在沃尔姆斯帝国会议上拒绝收回主张', '1521年4月，路德持皇帝的通行保证来到沃尔姆斯，17日和18日在皇帝查理五世和帝国诸侯面前受讯。他表示除非被《圣经》和明白的道理驳倒，否则不能也不愿收回任何主张；“这是我的立场”一语出自后来的传说。5月，皇帝颁布敕令，宣布他不受法律保护。'],
        ['Worms', 'Refuses to recant at the Diet of Worms', 'Luther came to Worms in April 1521 under an imperial safe-conduct. Before the young Emperor Charles V and the princes on 17 and 18 April, he said that unless he was refuted by Scripture and plain reason he could not and would not retract anything. The words "Here I stand" are a later tradition. In May the Edict of Worms declared him an outlaw.'],
        { wiki: { zh: '沃尔姆斯会议', en: 'Diet of Worms' } }),
      w(1521, 10.31, 50.97,
        ['瓦特堡（艾森纳赫附近）', '隐居瓦特堡，将《新约》译为德文', '返程途中，选帝侯腓特烈派人假扮劫匪，把路德“绑”进艾森纳赫城外的瓦特堡加以保护。他蓄起须发，化名“容克约尔格”，在此藏身近十个月，仅用约十一周就把《新约》从希腊文译成德文，译本于1522年9月出版。'],
        ['Wartburg Castle (near Eisenach)', 'Hidden at the Wartburg, translates the New Testament', 'On his way home Luther was "kidnapped" by agents of Elector Frederick and hidden for his own safety in the Wartburg above Eisenach. Growing his hair and beard and passing as "Junker Jörg", he stayed almost ten months and translated the New Testament from Greek into German in about eleven weeks. It was published in September 1522.'],
        { wiki: { zh: '瓦尔特堡', en: 'Wartburg' } }),
      w(1522, 12.65, 51.87,
        ['维滕贝格', '返回维滕贝格领导改革', '路德不在期间，卡尔施塔特等人在维滕贝格推行激进改革，出现捣毁圣像的骚动。1522年3月路德不顾选帝侯劝阻赶回，连续八天登坛讲道，主张改革应凭讲道和劝说循序进行，不可强迫，城中秩序随之恢复。'],
        ['Wittenberg', 'Returns to Wittenberg to lead the reform', "In Luther's absence Andreas Karlstadt and others pushed through radical changes at Wittenberg, and images were smashed in the churches. Against the elector's advice Luther came back in March 1522 and preached on eight successive days, arguing that reform must come through preaching and persuasion, not force. Order was restored."]),
      w(1525, 12.6525, 51.8642,
        ['维滕贝格（黑修道院，今路德故居）', '与卡塔琳娜·冯·博拉结婚', '1525年德意志农民战争席卷南部和中部，路德先是劝和，继而撰文痛斥起事农民，呼吁诸侯严厉镇压，为此失去不少下层民众的拥护。同年6月，他与逃出修道院的前修女卡塔琳娜·冯·博拉结婚，在原先的奥古斯丁修道院里安家，育有六个子女。'],
        ['Wittenberg (the Black Cloister, now the Lutherhaus)', 'Marries Katharina von Bora', "When the Peasants' War swept southern and central Germany in 1525, Luther first urged peace and then called on the princes to crush the rebels, which cost him much popular support. That June he married Katharina von Bora, a former nun who had fled her convent. They set up house in the old Augustinian friary and had six children."],
        { wiki: { zh: '路德故居', en: 'Lutherhaus' } }),
      w(1529, 8.77, 50.81,
        ['马尔堡', '在马尔堡会谈中与茨温利分歧', '1529年10月，黑森伯爵菲利普邀请路德与瑞士改革家茨温利到马尔堡城堡会谈，希望新教各派联合。双方在十五条信纲中的十四条上达成一致，唯独对圣餐中基督是否真实临在各执己见，路德派与瑞士改革派从此分道而行。'],
        ['Marburg', 'Fails to agree with Zwingli at the Marburg Colloquy', 'In October 1529 Landgrave Philip of Hesse brought Luther and the Swiss reformer Huldrych Zwingli together at Marburg Castle in the hope of uniting the Protestants. They agreed on fourteen of fifteen articles but not on whether Christ is really present in the bread and wine of the Eucharist, and the Lutheran and Reformed churches went separate ways.']),
      w(1530, 10.98, 50.26,
        ['科堡（科堡要塞）', '避居科堡，遥助《奥格斯堡信纲》', '1530年皇帝在奥格斯堡召开帝国会议。路德仍是帝国通缉之人，只能留在萨克森选侯国最南端的科堡要塞，住了近半年，靠书信为前方出谋划策。6月25日，同事梅兰希顿起草的《奥格斯堡信纲》在会上宣读，成为路德宗的基本信条。'],
        ['Coburg (Veste Coburg)', 'Stays at Coburg during the Diet of Augsburg', 'When the emperor held a diet at Augsburg in 1530, Luther, still an outlaw, could go no further than the fortress of Coburg at the southern edge of Electoral Saxony, where he spent nearly six months advising by letter. On 25 June the Augsburg Confession, drafted by his colleague Philip Melanchthon, was read to the diet; it became the basic Lutheran statement of faith.'],
        { wiki: { zh: '科堡要塞', en: 'Veste Coburg' } }),
      w(1534, 12.65, 51.87,
        ['维滕贝格', '出版德文《圣经》全译本', '路德与梅兰希顿等同事合作，历时十二年，从希伯来文译出《旧约》。1534年，附有克拉纳赫作坊木刻插图的德文《圣经》全本在维滕贝格出版。译文取法日常口语，流传极广，为近代标准德语奠定了基础。'],
        ['Wittenberg', 'Publishes the complete German Bible', 'Working with Melanchthon and other colleagues, Luther spent twelve years translating the Old Testament from Hebrew. In 1534 the complete German Bible was printed at Wittenberg with woodcuts from the workshop of Lucas Cranach. Written in the idiom of everyday speech and very widely read, it helped lay the foundations of modern standard German.'],
        { wiki: { zh: '路德圣经', en: 'Luther Bible' } }),
      w(1546, 11.55, 51.53,
        ['艾斯莱本', '病逝于故乡', '1546年初，年迈多病的路德冒着严寒回到艾斯莱本，为曼斯费尔德伯爵家族调解矿权和继承纠纷。争端刚刚了结，他便胸痛发作，于2月18日凌晨去世，享年62岁。遗体运回维滕贝格，葬于诸圣堂讲坛之下。'],
        ['Eisleben', 'Dies in the town of his birth', 'Early in 1546 the ailing Luther travelled through bitter cold to Eisleben to mediate a dispute over mining rights and inheritance among the counts of Mansfeld. The quarrel was barely settled when he suffered chest pains, and he died in the early hours of 18 February, aged 62. He was buried beneath the pulpit of the Castle Church in Wittenberg.']),
    ],
    wiki: { zh: '马丁·路德', en: 'Martin Luther' },
  },
  {
    id: 'suleiman',
    name: { zh: '苏莱曼一世', en: 'Suleiman the Magnificent' },
    birth: 1494, death: 1566,
    title: { zh: '奥斯曼帝国苏丹', en: 'Ottoman sultan' },
    region: 'west-asia',
    lineage: 'ottoman',
    sprite: 'horse',
    summary: {
      zh: '奥斯曼帝国第十位苏丹，在位46年，西方称“苏莱曼大帝”，本国称“立法者”。他亲征十余次，攻克贝尔格莱德、罗得岛，大败匈牙利，兵临维也纳城下，并征服两河流域与北非沿岸。他主持编订法典，建筑师锡南为他修建了苏莱曼尼耶清真寺，奥斯曼帝国在其治下达到鼎盛。',
      en: 'Tenth sultan of the Ottoman Empire, who reigned for 46 years and is known in the West as "the Magnificent" and in Turkey as "the Lawgiver". He led more than a dozen campaigns in person, taking Belgrade and Rhodes, destroying the Hungarian army at Mohács and besieging Vienna, and added Iraq and much of the North African coast to the empire. Under him Ottoman power, law and architecture reached their height.',
    },
    route: [
      w(1494, 39.72, 41.0,
        ['特拉布宗', '生于特拉布宗', '1494年11月，苏莱曼生于黑海南岸的特拉布宗，父亲是当时任特拉布宗总督的王子塞利姆，母亲为哈芙莎。他在这里度过童年，学习《古兰经》、历史、文学和军事，并按王室惯例学了一门手艺——金匠。'],
        ['Trabzon', 'Born at Trabzon', 'Suleiman was born in November 1494 at Trabzon on the Black Sea, where his father, Prince Selim, was governor; his mother was Hafsa. He spent his childhood there, studying the Quran, history, literature and the arts of war, and in keeping with dynastic custom he was trained in a craft, that of goldsmith.']),
      w(1509, 35.38, 45.03,
        ['卡法（今克里米亚费奥多西亚）', '少年出任卡法总督', '约1509年，十几岁的苏莱曼渡过黑海，出任克里米亚南岸卡法的总督。这座昔日热那亚人的商港是奥斯曼帝国与克里米亚汗国往来的门户。1512年，父亲塞利姆正是以此地为依托，借助克里米亚的兵力西进，逼迫祖父巴耶济德二世退位。'],
        ['Caffa (now Feodosia, Crimea)', 'Appointed governor of Caffa as a youth', 'Around 1509 the teenage Suleiman crossed the Black Sea to govern Caffa on the southern coast of Crimea, a former Genoese trading port and the Ottoman gateway to the Crimean Khanate. It was from here that his father Selim, with Crimean support, marched west and in 1512 forced Bayezid II to give up the throne.'],
        { sea: true }),
      w(1512, 28.98, 41.01,
        ['伊斯坦布尔', '父亲塞利姆一世即位，奉召回京', '1512年塞利姆一世夺得苏丹之位，随即出兵清除争位的兄弟。苏莱曼被从克里米亚召回都城，在父亲出征期间留守。次年局势平定，他被派往安纳托利亚西部的马尼萨。'],
        ['Istanbul', 'Recalled to the capital as his father takes the throne', 'Selim I seized the sultanate in 1512 and at once turned on the brothers who disputed it. Suleiman was recalled from the Crimea to the capital and remained there while his father campaigned against them. With the succession settled the following year, he was posted to Manisa in western Anatolia.'],
        { sea: true, via: [[35.6, 44.7], [29.25, 41.4]] }),
      w(1513, 27.43, 38.61,
        ['马尼萨', '任马尼萨总督，历练七年', '1513年起，苏莱曼出任萨鲁汉（马尼萨）总督。父亲东征波斯、南灭马穆鲁克王朝期间，他曾奉命到埃迪尔内镇守帝国的欧洲部分。在马尼萨，他结识了后来官至大维齐尔的希腊裔侍从易卜拉欣。'],
        ['Manisa', 'Governs Manisa for seven years', 'From 1513 Suleiman governed the province of Saruhan from Manisa. While his father campaigned against Persia and conquered Mamluk Syria and Egypt, he was sent to Edirne to watch over the European provinces. At Manisa he formed his friendship with Ibrahim, the Greek-born page who would later be his grand vizier.']),
      w(1520, 28.98, 41.01,
        ['伊斯坦布尔', '即位为苏丹', '1520年9月塞利姆一世去世，25岁的苏莱曼由马尼萨赶到都城，于9月30日即位，未遇任何兄弟争位。他继承的帝国刚刚吞并叙利亚、埃及和汉志，国库充盈。即位之初，他准许被父亲强迁到都城的埃及工匠返乡，并赔偿货物被没收的商人。'],
        ['Istanbul', 'Becomes sultan', 'Selim I died in September 1520, and the 25-year-old Suleiman hurried from Manisa to the capital, where he was enthroned on 30 September without any rival. He inherited an empire that had just absorbed Syria, Egypt and the Hejaz, and a full treasury. Among his first acts he let craftsmen deported from Egypt return home and compensated merchants whose goods his father had confiscated.']),
      w(1521, 20.46, 44.82,
        ['贝尔格莱德', '攻克贝尔格莱德', '匈牙利拒绝纳贡并虐待奥斯曼使者，苏莱曼即位次年便亲征多瑙河。他先取下萨瓦河上的沙巴茨，再水陆合围贝尔格莱德，1521年8月29日守军投降。这座曾令曾祖父穆罕默德二世受挫的要塞易手，通往匈牙利平原的大门由此洞开。'],
        ['Belgrade', 'Captures Belgrade', 'Hungary had refused tribute and mistreated an Ottoman envoy, and in the year after his accession Suleiman marched to the Danube. He took Šabac on the Sava and then invested Belgrade by land and river; the garrison surrendered on 29 August 1521. The fortress that had defied his great-grandfather Mehmed II now opened the way into the Hungarian plain.']),
      w(1522, 28.22, 36.44,
        ['罗得岛', '迫使医院骑士团撤离罗得岛', '医院骑士团盘踞罗得岛两百余年，劫掠往来埃及的航线。1522年夏，苏莱曼率大军登岛，围攻五个月，靠坑道爆破逐段摧毁城防。12月骑士团投降，获准带着武器于1523年元旦离岛，后来辗转落脚马耳他。'],
        ['Rhodes', 'Forces the Knights Hospitaller to leave Rhodes', 'The Knights Hospitaller had held Rhodes for two centuries, preying on the sea route to Egypt. Suleiman landed in summer 1522 and besieged the city for five months, wrecking its walls section by section with mines. The knights capitulated in December and were allowed to sail away with their arms on 1 January 1523; they later settled on Malta.'],
        { wiki: { zh: '罗得岛之围 (1522年)', en: 'Siege of Rhodes (1522)' } }),
      w(1526, 18.68, 45.99,
        ['莫哈奇', '大败匈牙利军', '1526年8月29日，苏莱曼在多瑙河畔的莫哈奇平原迎战匈牙利国王拉约什二世。匈牙利重骑兵冲入奥斯曼军阵后遭火炮和火枪齐射，不到两个小时即告溃败，年轻的国王在逃跑时溺死于溪流。苏莱曼随后进入布达，匈牙利王国从此分裂。'],
        ['Mohács', 'Crushes the Hungarian army', 'On 29 August 1526 Suleiman met King Louis II of Hungary on the plain of Mohács beside the Danube. The Hungarian heavy cavalry charged into massed Ottoman cannon and musket fire and the battle was lost in under two hours; the young king drowned in a stream as he fled. Suleiman went on to enter Buda, and the Hungarian kingdom broke apart.'],
        { wiki: { zh: '摩哈赤战役', en: 'Battle of Mohács' } }),
      w(1529, 16.37, 48.21,
        ['维也纳', '首次围攻维也纳未克', '哈布斯堡的斐迪南夺取布达后，苏莱曼于1529年再度北上，夺回布达，9月下旬兵临维也纳。连绵秋雨迫使重炮留在途中，守军则不断挫败坑道爆破和突击。10月中旬天气转寒、粮草不继，他下令撤围，这里成为奥斯曼在中欧扩张的极限。'],
        ['Vienna', 'Besieges Vienna for the first time, without success', 'After Ferdinand of Habsburg seized Buda, Suleiman marched north again in 1529, retook the city and reached Vienna in late September. Heavy autumn rains had forced him to leave his big guns behind, and the defenders foiled his mines and assaults. In mid-October, short of supplies and with winter coming on, he raised the siege; Vienna marked the limit of Ottoman expansion in central Europe.'],
        { event: 'siege-of-vienna-1529' }),
      w(1532, 16.54, 47.39,
        ['克塞格（匈牙利西部，德语称京斯）', '再征维也纳，受阻于克塞格', '1532年苏莱曼再次率大军西进，意在与皇帝查理五世决战。8月，大军在边境小城克塞格被克罗地亚将领尤里希奇率领的数百名守军拖住三个多星期。时令已晚，苏莱曼放弃进攻维也纳，转而蹂躏施蒂利亚后班师，次年与哈布斯堡议和。'],
        ['Kőszeg (western Hungary; German Güns)', 'Second march on Vienna stalls at Kőszeg', 'In 1532 Suleiman again led a great army west, hoping to bring Emperor Charles V to battle. In August it was held up for more than three weeks before the small border town of Kőszeg, defended by a few hundred men under the Croatian captain Nikola Jurišić. With the season far gone, Suleiman gave up the attack on Vienna, raided Styria and went home.']),
      w(1534, 46.29, 38.08,
        ['大不里士', '东征萨法维波斯，进入大不里士', '西线暂告平静后，苏莱曼转而对付什叶派的萨法维王朝。1534年夏，大维齐尔易卜拉欣帕夏先行占领其都城大不里士，苏莱曼于9月赶到会合。波斯国王太美斯普一世避而不战，坚壁清野，奥斯曼军在严寒的山区损失了大量人畜。'],
        ['Tabriz', 'Enters Tabriz in his first Persian campaign', 'With the western front quiet, Suleiman turned against the Shia Safavids of Persia. In summer 1534 Grand Vizier Ibrahim Pasha occupied their capital, Tabriz, where the sultan joined him in September. Shah Tahmasp avoided battle and laid waste the country, and the Ottoman army lost many men and animals crossing the mountains in the cold.']),
      w(1534, 44.36, 33.31,
        ['巴格达', '征服巴格达', '1534年底，苏莱曼翻越扎格罗斯山脉南下，巴格达不战而降。他在此过冬，下令重修逊尼派教法学家阿布·哈尼法的陵墓，并朝谒纳杰夫和卡尔巴拉的什叶派圣地。两河流域自此并入奥斯曼帝国，帝国的势力抵达波斯湾。'],
        ['Baghdad', 'Takes Baghdad', 'At the end of 1534 Suleiman crossed the Zagros and Baghdad surrendered without a fight. Wintering there, he had the tomb of the Sunni jurist Abu Hanifa restored and visited the Shia shrines of Najaf and Karbala. Iraq passed under Ottoman rule, giving the empire access to the Persian Gulf.']),
      w(1541, 19.04, 47.5,
        ['布达（今布达佩斯）', '吞并匈牙利中部，设布达行省', '苏莱曼扶植的匈牙利国王佐波尧1540年去世，哈布斯堡军队趁机围攻布达。1541年苏莱曼亲征解围，8月底兵不血刃占据王宫，把匈牙利中部改为帝国直辖的行省。此后土耳其人统治布达达145年之久。'],
        ['Buda (now Budapest)', 'Annexes central Hungary as the province of Buda', 'John Zápolya, the king of Hungary whom Suleiman had backed, died in 1540 and Habsburg troops laid siege to Buda. Suleiman relieved the city in 1541 and at the end of August occupied the royal castle without bloodshed, turning central Hungary into a directly ruled province. Buda remained Ottoman for 145 years.'],
        { wiki: { zh: '布达城堡', en: 'Buda Castle' } }),
      w(1553, 34.05, 37.51,
        ['埃雷利（今土耳其科尼亚省）', '东征途中处死长子穆斯塔法', '1553年苏莱曼第三次东征波斯，行至科尼亚以东的埃雷利时，把深得军心的长子穆斯塔法召入御帐，以谋反的嫌疑当场绞死。当时人多归咎于皇后许蕾姆和她的女婿、大维齐尔鲁斯坦帕夏，近卫军中一片不平之声。'],
        ['Ereğli (Konya Province, Turkey)', 'Has his eldest son Mustafa executed', 'Marching east on his third Persian campaign in 1553, Suleiman halted at Ereğli, beyond Konya, summoned his eldest surviving son Mustafa, a favourite of the army, to the imperial tent and had him strangled on suspicion of treason. Contemporaries blamed his wife Hürrem and her son-in-law, the grand vizier Rüstem Pasha, and the Janissaries were close to mutiny.']),
      w(1555, 35.83, 40.65,
        ['阿马西亚', '与萨法维王朝缔结《阿马西亚和约》', '三次东征都未能迫使波斯决战。1555年5月，苏莱曼在冬营所在的阿马西亚与太美斯普一世的使者缔约，这是两国间的第一份正式和约：伊拉克和安纳托利亚东部归奥斯曼，大不里士和高加索东部归波斯。哈布斯堡的使节布斯贝克也在此觐见了他。'],
        ['Amasya', 'Makes the Peace of Amasya with the Safavids', "Three eastern campaigns had failed to force a decisive battle. In May 1555, at his winter quarters in Amasya, Suleiman concluded the first formal peace between the two empires with Shah Tahmasp's envoys: Iraq and eastern Anatolia went to the Ottomans, Tabriz and the eastern Caucasus to Persia. The Habsburg envoy Busbecq also had an audience with him there."]),
      w(1557, 28.964, 41.016,
        ['伊斯坦布尔（苏莱曼尼耶清真寺）', '苏莱曼尼耶清真寺落成', '1550年，苏莱曼命首席建筑师锡南在俯瞰金角湾的山丘上兴建以他命名的清真寺，1557年落成。建筑群还包括学院、医院、济贫厨房和浴场。这一时期他主持编订法典，协调苏丹法令与伊斯兰教法，因而在本国被称为“立法者”。'],
        ['Istanbul (Süleymaniye Mosque)', 'The Süleymaniye Mosque is completed', 'In 1550 Suleiman ordered his chief architect, Sinan, to build a mosque bearing his name on a hill above the Golden Horn; it was finished in 1557. The complex included colleges, a hospital, a public kitchen and baths. In these years he also oversaw the codification that reconciled sultanic decrees with Islamic law, earning him the name "Lawgiver".'],
        { wiki: { zh: '苏莱曼尼耶清真寺', en: 'Süleymaniye Mosque' } }),
      w(1566, 17.8, 46.05,
        ['锡盖特堡（匈牙利南部）', '围攻锡盖特堡期间病逝军中', '1566年，71岁的苏莱曼抱病发动第十三次亲征，围攻克罗地亚贵族兹林斯基据守的锡盖特堡。9月初的一个夜里他在营帐中去世，一两天后城堡陷落。大维齐尔索科卢秘不发丧数十日，直到新君塞利姆二世赶来。遗体归葬苏莱曼尼耶清真寺。'],
        ['Szigetvár (southern Hungary)', 'Dies in camp during the siege of Szigetvár', 'In 1566 Suleiman, aged 71 and ailing, set out on his thirteenth campaign and besieged Szigetvár, held by the Croatian nobleman Nikola Zrinski. He died in his tent in early September, a day or so before the fortress fell. Grand Vizier Sokollu Mehmed Pasha concealed the death for weeks until the heir, Selim II, arrived. Suleiman was buried at the Süleymaniye.'],
        { wiki: { zh: '锡盖特堡围城战', en: 'Siege of Szigetvár' } }),
    ],
    wiki: { zh: '苏莱曼一世', en: 'Suleiman the Magnificent' },
  },
  {
    id: 'elizabeth-i',
    name: { zh: '伊丽莎白一世', en: 'Elizabeth I' },
    birth: 1533, death: 1603,
    title: { zh: '英格兰女王', en: 'Queen of England' },
    region: 'europe',
    lineage: 'britain',
    sprite: 'crown',
    summary: {
      zh: '英格兰女王，都铎王朝最后一位君主，终身未婚，被称为“童贞女王”。她在位44年，确立英国国教，1588年击败西班牙无敌舰队，鼓励海外探险与贸易，莎士比亚等文艺巨匠辈出，史称“伊丽莎白时代”，英格兰由此崛起为欧洲强国。',
      en: 'Queen of England and Ireland and the last Tudor monarch; she never married and was known as the Virgin Queen. In a reign of 44 years she established a moderate Protestant settlement for the Church of England, saw off the Spanish Armada in 1588 and encouraged overseas trade and exploration. The age of Shakespeare, Marlowe and Drake is remembered as the Elizabethan era, in which England emerged as a leading European power.',
    },
    route: [
      w(1533, 0.0, 51.48,
        ['格林尼治（普拉森舍宫，今伦敦）', '生于格林尼治宫，父为亨利八世', '1533年9月7日，伊丽莎白生于泰晤士河畔的格林尼治宫，是亨利八世与第二任王后安妮·博林的女儿。为迎娶安妮，亨利不惜与罗马教廷决裂；一心盼望男性继承人的他，对又添一位公主颇为失望。'],
        ['Greenwich (Palace of Placentia, now London)', 'Born at Greenwich Palace, daughter of Henry VIII', 'Elizabeth was born on 7 September 1533 at Greenwich Palace on the Thames, the daughter of Henry VIII and his second queen, Anne Boleyn. Henry had broken with Rome in order to marry Anne, and having counted on a male heir he was disappointed to be given another princess.']),
      w(1536, -0.22, 51.76,
        ['哈特菲尔德（赫特福德郡）', '母亲被处决，失去公主名分', '伊丽莎白出生三个月后就有了自己的宫室，设在伦敦以北的哈特菲尔德。1536年5月，母亲安妮·博林以通奸、叛国的罪名被斩首，不满3岁的她被宣布为私生女。此后她在几处王室庄园长大，受到出色的人文主义教育，通晓拉丁文、法文和意大利文。'],
        ['Hatfield (Hertfordshire)', 'Loses her mother and her title of princess', 'Elizabeth was given her own household at Hatfield, north of London, when she was three months old. In May 1536 her mother was beheaded on charges of adultery and treason, and the child, not yet three, was declared illegitimate. Brought up at Hatfield and other royal manors, she received an excellent humanist education and learned Latin, French and Italian.']),
      w(1547, -0.168, 51.484,
        ['切尔西（今伦敦）', '寄居继母凯瑟琳·帕尔家中', '1547年亨利八世去世，同父异母的弟弟爱德华六世继位，13岁的伊丽莎白搬到切尔西与继母凯瑟琳·帕尔同住。凯瑟琳的新夫、海军大臣托马斯·西摩对她举止轻佻，她因此被送走。1549年西摩以叛国罪被处死，她也受到盘问，从此行事格外谨慎。'],
        ['Chelsea (now London)', 'Lives with her stepmother Catherine Parr', "Henry VIII died in 1547 and was succeeded by Elizabeth's half-brother Edward VI. Aged thirteen, she went to live at Chelsea with her stepmother Catherine Parr, whose new husband, Thomas Seymour, behaved so familiarly towards her that she was sent away. When Seymour was executed for treason in 1549 she was closely questioned, a lesson in caution she did not forget."]),
      w(1554, -0.076, 51.508,
        ['伦敦塔', '被怀疑参与叛乱，遭玛丽一世囚禁', '1553年信奉天主教的姐姐玛丽一世即位。次年初，反对女王与西班牙王储联姻的怀亚特起兵失败，有人指伊丽莎白与闻其事。1554年3月她被押入伦敦塔，关了两个月。她始终否认，审讯者也没有拿到确证。'],
        ['Tower of London', 'Imprisoned by Mary I on suspicion of plotting', "Elizabeth's Catholic half-sister Mary I came to the throne in 1553. Early the next year Sir Thomas Wyatt rose in revolt against the queen's planned Spanish marriage, and Elizabeth was suspected of complicity. In March 1554 she was taken to the Tower and held for two months. She denied everything, and no firm evidence was found against her."],
        { wiki: { zh: '伦敦塔', en: 'Tower of London' } }),
      w(1554, -1.362, 51.845,
        ['伍德斯托克（牛津郡）', '软禁于伍德斯托克', '1554年5月，伊丽莎白被移出伦敦塔，押往牛津郡的伍德斯托克王室庄园，在此被看管了将近一年，沿途有民众向她欢呼。1555年她获准回到宫中，后又返回哈特菲尔德；玛丽一世无嗣，她成了事实上的王位继承人。'],
        ['Woodstock (Oxfordshire)', 'Held under house arrest at Woodstock', 'In May 1554 Elizabeth was moved from the Tower to the royal manor of Woodstock in Oxfordshire, where she was kept under guard for nearly a year; crowds cheered her along the way. She was allowed back to court in 1555 and later returned to Hatfield. As Mary remained childless, Elizabeth was the heir in all but name.']),
      w(1558, -0.22, 51.76,
        ['哈特菲尔德', '得知自己即位为英格兰女王', '1558年11月17日玛丽一世去世，消息传到哈特菲尔德。相传伊丽莎白当时正在园中一棵橡树下，闻讯后引《诗篇》说：“这是耶和华所做的，在我们眼中看为稀奇。”三天后她在此召开第一次枢密会议，任命威廉·塞西尔为国务大臣。'],
        ['Hatfield', 'Learns that she is queen of England', "Mary I died on 17 November 1558 and the news was brought to Hatfield. According to tradition Elizabeth was under an oak in the park and answered with a verse from the Psalms: \"This is the Lord's doing; it is marvellous in our eyes.\" Three days later she held her first council there and named William Cecil her principal secretary."],
        { wiki: { zh: '哈特菲尔德庄园', en: 'Hatfield House' } }),
      w(1559, -0.127, 51.4994,
        ['威斯敏斯特（今伦敦）', '在威斯敏斯特教堂加冕', '1559年1月15日，伊丽莎白在威斯敏斯特教堂加冕，日期由占星家约翰·迪伊择定。同年议会通过《至尊法》和《信仰划一法》，重新确立脱离罗马的英格兰国教会，由她任“最高管理者”，礼仪上则保留不少旧制，力求折中。'],
        ['Westminster (now London)', 'Crowned in Westminster Abbey', 'Elizabeth was crowned in Westminster Abbey on 15 January 1559, a date chosen with the advice of the astrologer John Dee. That year Parliament passed the Acts of Supremacy and Uniformity, restoring a Church of England independent of Rome with the queen as its Supreme Governor, while keeping much traditional ceremony in a deliberate middle way.'],
        { wiki: { zh: '西敏寺', en: 'Westminster Abbey' } }),
      w(1562, -0.3377, 51.4036,
        ['汉普顿宫', '在汉普顿宫染天花，几乎不治', '1562年10月，29岁的伊丽莎白在汉普顿宫染上天花，一度病危，群臣已在商议继位人选。她康复后，议会一再请求她结婚或指定继承人，她始终不肯明确表态，转而把各国王室的求婚当作外交筹码。'],
        ['Hampton Court Palace', 'Nearly dies of smallpox at Hampton Court', 'In October 1562 the 29-year-old queen fell ill with smallpox at Hampton Court and lay close to death while her councillors debated the succession. After she recovered, Parliament repeatedly pressed her to marry or name an heir. She would do neither, and instead used the courtships of foreign princes as an instrument of diplomacy.'],
        { wiki: { zh: '汉普顿宫', en: 'Hampton Court Palace' } }),
      w(1575, -1.5925, 52.3478,
        ['凯尼尔沃思城堡（沃里克郡）', '巡幸凯尼尔沃思，莱斯特伯爵盛宴款待', '伊丽莎白几乎每年夏天都带着宫廷出巡各郡，住在贵族家中，既省开支，又让臣民得见君主。1575年7月，她在宠臣莱斯特伯爵罗伯特·达德利的凯尼尔沃思城堡停留19天，其间焰火、水上表演和假面剧接连不断，是她在位期间最铺张的一次款待。'],
        ['Kenilworth Castle (Warwickshire)', 'Entertained by the Earl of Leicester at Kenilworth', 'Almost every summer Elizabeth took her court on progress through the counties, lodging with her nobles to save money and to be seen by her subjects. In July 1575 she spent nineteen days at Kenilworth Castle with her favourite Robert Dudley, Earl of Leicester, amid fireworks, water pageants and masques, the most lavish entertainment of her reign.'],
        { wiki: { zh: '凯尼尔沃思城堡', en: 'Kenilworth Castle' } }),
      w(1581, -0.027, 51.482,
        ['德特福德（今伦敦）', '登上“金鹿”号，册封德雷克为骑士', '1580年，弗朗西斯·德雷克完成环球航行，带回从西班牙殖民地和船只上劫得的大量金银，女王是这次航行的秘密出资人之一。1581年4月4日，她来到停泊在德特福德的“金鹿”号上赴宴，并在甲板上册封德雷克为骑士，英西关系进一步恶化。'],
        ['Deptford (now London)', 'Knights Francis Drake aboard the Golden Hind', 'Francis Drake returned in 1580 from his voyage round the world with a fortune in Spanish treasure, in which the queen had been a secret investor. On 4 April 1581 she dined aboard the Golden Hind at Deptford and had Drake knighted on deck, an open affront to Spain.'],
        { wiki: { zh: '金鹿号', en: 'Golden Hind' } }),
      w(1587, 0.0, 51.48,
        ['格林尼治', '签署苏格兰女王玛丽的死刑令', '信奉天主教的苏格兰女王玛丽1568年逃入英格兰，被软禁近19年，多起谋刺伊丽莎白的密谋都打着她的旗号。1586年巴宾顿阴谋败露，玛丽被判死罪。1587年2月1日伊丽莎白在格林尼治签署死刑令，一周后玛丽被斩首；女王事后声称死刑令未经她同意就已发出。'],
        ['Greenwich', 'Signs the death warrant of Mary, Queen of Scots', 'The Catholic Mary, Queen of Scots, fled to England in 1568 and was held captive for almost nineteen years, the focus of repeated plots against Elizabeth. After the Babington plot of 1586 she was condemned. Elizabeth signed the warrant at Greenwich on 1 February 1587 and Mary was beheaded at Fotheringhay a week later; the queen claimed it had been sent without her consent.']),
      w(1588, 0.37, 51.46,
        ['蒂尔伯里（埃塞克斯郡）', '检阅军队，发表抗击无敌舰队的演说', '1588年夏，西班牙无敌舰队驶入英吉利海峡，在格拉沃利讷海战中受挫后被风吹向北海。8月9日（旧历），伊丽莎白来到泰晤士河口的蒂尔伯里军营，检阅防备登陆的部队。据流传的演说辞，她说：“我虽只有一副柔弱女子的身躯，却有一颗国王的心。”'],
        ['Tilbury (Essex)', 'Reviews her troops and speaks against the Armada', 'In summer 1588 the Spanish Armada entered the Channel, was mauled off Gravelines and was driven into the North Sea. On 9 August (Old Style) Elizabeth came to the camp at Tilbury on the Thames to review the army raised against invasion. In the speech attributed to her she had "the body of a weak and feeble woman" but "the heart and stomach of a king".'],
        { event: 'spanish-armada' }),
      w(1601, -0.1255, 51.5045,
        ['白厅宫（今伦敦）', '在白厅发表“黄金演说”', '女王晚年，对西班牙和爱尔兰的战事耗费巨大，专卖特许又招致民怨。1601年2月，昔日宠臣埃塞克斯伯爵在伦敦起事，失败后被处死。同年11月30日，她在白厅宫接见下院代表，答应整顿专卖权，并说自己王冠的荣耀在于“以你们的爱戴治国”。'],
        ['Palace of Whitehall (now London)', 'Delivers her "Golden Speech" at Whitehall', "Elizabeth's last years were strained by costly wars with Spain and in Ireland and by anger at royal monopolies. In February 1601 her former favourite the Earl of Essex attempted a rising in London and was executed. On 30 November she received members of the Commons at Whitehall, promised reform and told them the glory of her crown was to have reigned with their loves."]),
      w(1603, -0.31, 51.46,
        ['里士满宫（今伦敦里士满）', '病逝，都铎王朝终结', '1603年初，伊丽莎白移居泰晤士河上游的里士满宫，此后日渐消沉，不肯卧床，也不愿进食。3月24日凌晨她在此去世，享年69岁。枢密院随即宣布苏格兰国王詹姆斯六世继位，是为英格兰的詹姆斯一世，英格兰与苏格兰从此共戴一君。'],
        ['Richmond Palace (Richmond, London)', 'Dies, ending the Tudor dynasty', 'Early in 1603 Elizabeth moved up the Thames to Richmond Palace, where she sank into melancholy and for days refused to take to her bed or eat. She died there in the early hours of 24 March, aged 69. The council at once proclaimed James VI of Scotland king as James I, uniting the crowns of England and Scotland.']),
    ],
    wiki: { zh: '伊丽莎白一世', en: 'Elizabeth I' },
  },
  {
    id: 'akbar',
    name: { zh: '阿克巴', en: 'Akbar' },
    birth: 1542, death: 1605,
    title: { zh: '莫卧儿帝国皇帝', en: 'Mughal emperor' },
    region: 'south-asia',
    lineage: 'india',
    sprite: 'horse',
    summary: {
      zh: '莫卧儿帝国第三代皇帝，1556年13岁即位，在位近50年。他通过征战和与拉杰普特王公联姻，把帝国从德里一隅扩展到北印度、孟加拉、古吉拉特、克什米尔和德干北部，并建立起曼萨卜达尔品级制度和统一的田赋制度。他废除对非穆斯林征收的人头税，召集各教学者论辩，倡导“普遍和平”，奠定了莫卧儿帝国百余年强盛的基础。',
      en: 'Third Mughal emperor, who came to the throne at thirteen in 1556 and reigned for almost fifty years. Through conquest and marriage alliances with Rajput princes he enlarged a small kingdom around Delhi into an empire covering northern India, Bengal, Gujarat, Kashmir and the northern Deccan, governed through a ranked service nobility and a uniform land-revenue system. He abolished the poll tax on non-Muslims, held debates among scholars of many faiths and promoted a policy of "universal peace".',
    },
    route: [
      w(1542, 69.74, 25.36,
        ['乌马尔科特（今巴基斯坦信德省）', '生于流亡途中的沙漠堡垒', '1542年10月15日，阿克巴生于信德沙漠边缘的乌马尔科特。其父胡马雍两年前被阿富汗人舍尔沙逐出德里，正四处流亡，是当地的拉杰普特首领收留了他和怀孕的妻子哈米达。相传胡马雍无物可赏，只能把一块麝香分给随从。'],
        ['Umarkot (Sindh, Pakistan)', "Born in a desert fort during his father's exile", 'Akbar was born on 15 October 1542 at Umarkot, on the edge of the Sindh desert. His father Humayun, driven from Delhi two years earlier by the Afghan Sher Shah, was a fugitive, and it was the local Rajput chief who sheltered him and his pregnant wife Hamida. Tradition says Humayun had nothing to give his followers but a broken pod of musk.']),
      w(1545, 69.17, 34.53,
        ['喀布尔', '在喀布尔与父亲团聚', '胡马雍西逃波斯时，不得不把一岁多的阿克巴留在坎大哈，由叔父抚养。1545年胡马雍借波斯之兵夺回坎大哈和喀布尔，父子重逢。阿克巴在喀布尔度过童年，喜好骑射、驯象和狩猎，却始终没有学会读写，日后靠旁人朗读来听书。'],
        ['Kabul', 'Reunited with his father at Kabul', 'When Humayun fled to Persia he had to leave his infant son behind at Kandahar in the care of an uncle. With Persian help Humayun recovered Kandahar and Kabul in 1545, and the two were reunited. Akbar spent his boyhood at Kabul, devoted to riding, elephants and the hunt; he never learned to read or write and in later life had books read aloud to him.']),
      w(1556, 75.15, 32.02,
        ['卡拉瑙尔（今印度旁遮普邦古尔达斯普尔县）', '13岁在军营中即位', '1555年胡马雍收复德里，半年后从藏书楼的台阶上跌落身亡。正在旁遮普随军的阿克巴得到消息，1556年2月14日，监护人拜拉姆汗在卡拉瑙尔的一处花园里筑起砖台，拥立他为皇帝，由拜拉姆汗摄政。'],
        ['Kalanaur (Gurdaspur district, Punjab, India)', 'Enthroned at thirteen in a military camp', 'Humayun regained Delhi in 1555 but died six months later after a fall on the stairs of his library. Akbar was on campaign in the Punjab when the news came. On 14 February 1556 his guardian Bairam Khan had him proclaimed emperor on a brick platform raised in a garden at Kalanaur, and governed as regent in his name.']),
      w(1556, 76.97, 29.39,
        ['帕尼帕特', '第二次帕尼帕特战役击败希穆', '阿富汗苏尔王朝的印度教大将希穆乘虚攻占德里，自立为王。1556年11月5日，两军在帕尼帕特交战，莫卧儿军本处下风，希穆却在象背上被流矢射中眼睛，全军溃散。希穆被俘后遭处死，德里和阿格拉重归莫卧儿人之手。'],
        ['Panipat', 'Defeats Hemu at the Second Battle of Panipat', 'Hemu, the Hindu general of the Afghan Sur dynasty, had seized Delhi and proclaimed himself king. The armies met at Panipat on 5 November 1556. The Mughals were hard pressed until an arrow struck Hemu in the eye as he directed the battle from his elephant, and his troops broke. He was captured and put to death, and Delhi and Agra returned to Mughal hands.'],
        { wiki: { zh: '第二次帕尼帕特战役', en: 'Second Battle of Panipat' } }),
      w(1562, 74.64, 26.45,
        ['阿杰梅尔', '朝谒苏菲圣陵，与拉杰普特联姻', '阿克巴1560年罢免拜拉姆汗，开始亲政。1562年初他首次前往阿杰梅尔朝谒苏菲圣徒穆因丁·契斯提的陵墓，途中琥珀堡的王公巴尔马尔前来归附，并把女儿嫁给他。此后拉杰普特王公纷纷入仕，成为帝国的支柱；他还相继废除了香客税和非穆斯林人头税。'],
        ['Ajmer', 'Visits a Sufi shrine and allies with the Rajputs', 'Akbar dismissed Bairam Khan in 1560 and took power himself. Early in 1562 he made his first pilgrimage to the tomb of the Sufi saint Muinuddin Chishti at Ajmer; on the way Raja Bharmal of Amber offered his allegiance and his daughter in marriage. Rajput princes then entered imperial service in numbers, and Akbar soon abolished the pilgrim tax and the poll tax on non-Muslims.'],
        { wiki: { zh: '阿杰梅尔圣陵', en: 'Ajmer Sharif Dargah' } }),
      w(1565, 78.02, 27.18,
        ['阿格拉', '兴建阿格拉红堡', '1565年，阿克巴下令拆除亚穆纳河畔的旧砖堡，用红砂岩重建阿格拉堡，约八年后完工。弧形城墙高约20米，周长2公里有余，堡内据记载曾有数百座建筑。阿格拉由此成为帝国的都城和国库所在。'],
        ['Agra', 'Builds the red sandstone fort at Agra', 'In 1565 Akbar ordered the old brick fort on the Yamuna pulled down and rebuilt in red sandstone, a task that took about eight years. Its curving walls rise some 20 metres and run for more than two kilometres, and chroniclers record hundreds of buildings inside. Agra Fort became the seat of the court and the imperial treasury.'],
        { wiki: { zh: '阿格拉堡', en: 'Agra Fort' } }),
      w(1568, 74.645, 24.887,
        ['奇陶尔加尔（今印度拉贾斯坦邦）', '攻陷梅瓦尔的奇陶尔堡', '梅瓦尔的拉纳在拉杰普特诸王中地位最尊，始终拒不臣服。1567年10月阿克巴亲自围攻其都城奇陶尔堡，挖掘坑道、构筑掩体，历时四个月，于1568年2月破城。守军战至最后，城中妇女举火自焚；阿克巴随后下令屠杀城内军民，据史书记载死者数以万计。'],
        ['Chittorgarh (Rajasthan, India)', 'Storms the Mewar fortress of Chittor', 'The Rana of Mewar, the most senior of the Rajput rulers, refused to submit. From October 1567 Akbar besieged his capital, the hill fortress of Chittor, driving mines and covered approaches for four months until it fell in February 1568. The garrison fought to the last and the women burned themselves; Akbar then ordered a massacre of those inside, and chroniclers put the dead in the tens of thousands.'],
        { wiki: { zh: '奇托尔加尔堡', en: 'Chittor Fort' } }),
      w(1571, 77.66, 27.09,
        ['法泰赫普尔西克里', '在西克里营建新都', '阿克巴久无子嗣，曾求教于隐居西克里的苏菲长老萨利姆·契斯提，长老预言他将得子。1569年皇子萨利姆（后来的贾汉吉尔）在此出生。1571年起，阿克巴在这处山冈上兴建新都“胜利之城”，融合波斯与印度式样的红砂岩宫殿和清真寺保存至今。'],
        ['Fatehpur Sikri', 'Founds a new capital at Sikri', 'Long without an heir, Akbar had sought the blessing of Salim Chishti, a Sufi holy man living at Sikri, who foretold the birth of a son. Prince Salim, the future Jahangir, was born there in 1569. From 1571 Akbar built a new capital on the ridge, Fatehpur Sikri, the "City of Victory", whose red sandstone palaces and mosque blend Persian and Indian styles.'],
        { event: 'fatehpur-sikri' }),
      w(1573, 72.58, 23.03,
        ['艾哈迈达巴德', '征服古吉拉特', '1572年阿克巴进军富庶的古吉拉特苏丹国，几乎未遇抵抗便占领艾哈迈达巴德，并在坎贝第一次见到大海，接见了葡萄牙商人。次年当地发生叛乱，他率少数骑兵从法泰赫普尔西克里疾驰约800公里，据称只用了9天，一战平定。帝国由此获得出海口。'],
        ['Ahmedabad', 'Conquers Gujarat', 'In 1572 Akbar invaded the rich sultanate of Gujarat and took Ahmedabad with little resistance; at Cambay he saw the sea for the first time and met Portuguese merchants. When a revolt broke out the next year he rode some 800 kilometres from Fatehpur Sikri with a small force, reportedly in nine days, and crushed it in a single battle. The empire now had ports on the Arabian Sea.']),
      w(1574, 85.14, 25.6,
        ['巴特那', '顺恒河东下，夺取巴特那', '孟加拉的阿富汗统治者达乌德汗自立称王。1574年雨季，阿克巴率船队沿亚穆纳河、恒河顺流而下，攻下对岸的哈吉布尔后，巴特那守军弃城而逃。此后两年，他的将领追击达乌德汗，1576年将孟加拉并入帝国。'],
        ['Patna', 'Sails down the Ganges to take Patna', 'Daud Khan, the Afghan ruler of Bengal, had declared his independence. During the monsoon of 1574 Akbar took a fleet of boats down the Yamuna and the Ganges; once the fort of Hajipur across the river had fallen, the garrison of Patna fled. His generals pursued Daud Khan over the next two years, and Bengal was annexed in 1576.']),
      w(1575, 77.66, 27.09,
        ['法泰赫普尔西克里', '设“礼拜殿”，召集各教学者论辩', '1575年，阿克巴在新都建起“礼拜殿”，每周四晚间主持宗教讨论，起初只限穆斯林学者，后来陆续请来印度教徒、耆那教徒和祆教徒，1580年又迎来果阿的耶稣会士。他由此提出“普遍和平”的原则，1582年还在近臣中倡立名为“神圣宗教”的小团体。'],
        ['Fatehpur Sikri', 'Opens the House of Worship to debate religion', 'In 1575 Akbar built the Ibadat Khana, or House of Worship, where he presided over religious discussions on Thursday evenings. At first only Muslim scholars took part; Hindus, Jains and Zoroastrians followed, and in 1580 Jesuits arrived from Goa. From these debates came his principle of "universal peace", and in 1582 he formed a small circle of disciples known as the Din-i Ilahi.']),
      w(1581, 69.17, 34.53,
        ['喀布尔', '西征喀布尔，慑服异母弟', '1580年，孟加拉和比哈尔的军官因不满改革而叛乱，并拥戴统治喀布尔的阿克巴异母弟米尔扎·哈基姆，后者趁机进犯旁遮普。阿克巴亲率大军越过印度河，1581年8月进入喀布尔，哈基姆遁入山中。阿克巴宽恕了他，把喀布尔交还其家族管理。'],
        ['Kabul', 'Marches on Kabul to subdue his half-brother', "In 1580 officers in Bengal and Bihar, resentful of Akbar's reforms, rebelled and declared for his half-brother Mirza Hakim, the ruler of Kabul, who invaded the Punjab. Akbar led a large army across the Indus and entered Kabul in August 1581 while Hakim took to the hills. Akbar pardoned him and left Kabul in his family's keeping."]),
      w(1585, 74.31, 31.59,
        ['拉合尔', '移驻拉合尔，经略西北', '1585年米尔扎·哈基姆去世，乌兹别克人又在中亚崛起，阿克巴遂把朝廷迁到拉合尔，在此驻留十三年，重修了拉合尔堡。其间他的军队先后兼并克什米尔、信德和俾路支，1595年又收回坎大哈，帝国的西北边疆得以巩固。'],
        ['Lahore', 'Moves his court to Lahore to secure the north-west', "After Mirza Hakim died in 1585, and with the Uzbeks growing strong in Central Asia, Akbar moved his court to Lahore, where it stayed for thirteen years and where he rebuilt the fort. From there his armies annexed Kashmir, Sindh and Baluchistan, and in 1595 Kandahar was recovered, securing the empire's north-western frontier."],
        { wiki: { zh: '拉合尔城堡', en: 'Lahore Fort' } }),
      w(1589, 74.8, 34.08,
        ['斯利那加（克什米尔）', '初访克什米尔', '莫卧儿军队1586年征服克什米尔。1589年夏，阿克巴第一次翻越比尔本贾尔山来到斯利那加，泛舟湖上，对谷地的风光大为赞赏。此后他又两度前来，并下令在城中的哈里帕尔巴特山修筑城墙，克什米尔从此成为莫卧儿皇帝钟爱的避暑之地。'],
        ['Srinagar (Kashmir)', 'Visits Kashmir for the first time', 'Mughal forces conquered Kashmir in 1586. In the summer of 1589 Akbar crossed the Pir Panjal range to Srinagar for the first time and went boating on its lakes, delighted by the valley. He returned twice more and had a wall built around the hill of Hari Parbat in the city, and Kashmir became the favourite summer retreat of the Mughal emperors.']),
      w(1601, 76.29, 21.47,
        ['阿西尔格尔堡（今印度中央邦布尔汉普尔附近）', '南征德干，攻取阿西尔格尔', '阿克巴1598年离开拉合尔，次年南下亲自督师德干。1600年他的军队攻陷艾哈迈德讷格尔城，他本人则围困坎德什王国的山顶要塞阿西尔格尔，1601年1月守军出降。这是他的最后一次征服；同年他因皇子萨利姆在安拉阿巴德抗命自立而赶回阿格拉。'],
        ['Asirgarh Fort (near Burhanpur, Madhya Pradesh, India)', 'Campaigns in the Deccan and takes Asirgarh', 'Akbar left Lahore in 1598 and the next year went south to direct the war in the Deccan himself. In 1600 his army stormed the city of Ahmadnagar while he blockaded Asirgarh, the hilltop stronghold of the kingdom of Khandesh, which surrendered in January 1601. It was his last conquest: that year he hurried back to Agra because his son Salim had set himself up in defiance at Allahabad.']),
      w(1605, 78.02, 27.18,
        ['阿格拉', '病逝于阿格拉，葬于锡坎德拉', '阿克巴晚年连丧两子，心腹史官阿布勒·法兹勒也在1602年被萨利姆指使人杀害。1605年10月阿克巴患痢疾，27日在阿格拉堡去世，享年63岁。他葬在城外锡坎德拉自己生前开始营建的陵墓中，萨利姆继位，称贾汉吉尔。'],
        ['Agra', 'Dies at Agra and is buried at Sikandra', "Akbar's last years were darkened by the deaths of two sons and by the murder in 1602 of his friend and chronicler Abul Fazl at Salim's instigation. He fell ill with dysentery in October 1605 and died in Agra Fort on the 27th, aged 63. He was buried at Sikandra outside the city, in a tomb he had begun himself, and Salim succeeded as Jahangir."],
        { wiki: { zh: '阿克巴陵', en: "Akbar's tomb" } }),
    ],
    wiki: { zh: '阿克巴', en: 'Akbar' },
  },
  {
    id: 'tokugawa-ieyasu',
    name: { zh: '德川家康', en: 'Tokugawa Ieyasu' },
    birth: 1543, death: 1616,
    title: { zh: '江户幕府初代将军', en: 'Founder of the Tokugawa shogunate' },
    region: 'east-asia',
    lineage: 'japan',
    sprite: 'horse',
    summary: {
      zh: '日本战国时代末期的大名，江户幕府的创建者。他生于三河冈崎，幼年先后在织田、今川两家做人质，后与织田信长结盟，又臣服于丰臣秀吉，受封关东。1600年他在关原之战中获胜，1603年就任征夷大将军，开创江户幕府；1615年攻灭丰臣氏，结束了百余年的战乱。德川氏此后统治日本260余年。',
      en: 'Japanese warlord of the late Warring States period and founder of the Tokugawa (Edo) shogunate. Born at Okazaki in Mikawa, he spent his boyhood as a hostage, became an ally of Oda Nobunaga and then a vassal of Toyotomi Hideyoshi, who moved him to the Kanto. Victory at Sekigahara in 1600 made him master of Japan; he was appointed shogun in 1603 and destroyed the Toyotomi at Osaka in 1615. His house ruled Japan for more than 260 years.',
    },
    route: [
      w(1543, 137.16, 34.956,
        ['冈崎城（今爱知县冈崎市）', '生于三河冈崎城', '1543年1月31日（天文十一年十二月二十六日），家康生于三河国冈崎城，幼名竹千代，父亲是城主松平广忠。松平氏势力弱小，夹在西面的织田氏与东面的今川氏之间。他尚在襁褓时，母亲於大就因娘家改投织田而被迫离婚。'],
        ['Okazaki Castle (Okazaki, Aichi)', 'Born at Okazaki Castle in Mikawa', 'Ieyasu was born on 31 January 1543 at Okazaki Castle in Mikawa Province and named Takechiyo. His father, Matsudaira Hirotada, was a minor lord squeezed between the Oda to the west and the Imagawa to the east. While the boy was still an infant his mother, Odai, was sent away after her own family went over to the Oda.'],
        { wiki: { zh: '冈崎城', en: 'Okazaki Castle' } }),
      w(1547, 136.908, 35.127,
        ['热田（今名古屋市热田区）', '被劫往尾张，沦为织田氏人质', '1547年，松平广忠为换取今川氏的援兵，把年幼的竹千代送往骏府做人质。按通行的说法，护送途中田原城主户田康光变节，把他转交给了尾张的织田信秀。竹千代被扣在热田等地约两年。'],
        ['Atsuta (now Atsuta Ward, Nagoya)', 'Seized on the road and held hostage by the Oda', 'In 1547 Hirotada agreed to send his young son to Sunpu as a hostage in return for Imagawa military help. According to the traditional account, the lord of Tahara who was escorting the boy betrayed him and handed him over to Oda Nobuhide of Owari instead. Takechiyo was held at Atsuta and elsewhere in Owari for about two years.']),
      w(1549, 138.383, 34.979,
        ['骏府（今静冈市）', '转为今川氏人质，在骏府长大', '1549年松平广忠去世，今川军俘获织田信秀之子，把竹千代交换回来，送往骏府。他在今川义元治下生活了十余年，在此元服，先后改名松平元信、元康，娶今川氏的亲族之女筑山殿为妻，并以今川部将的身份初次上阵。'],
        ['Sunpu (now Shizuoka)', 'Grows up at Sunpu as a hostage of the Imagawa', 'After Hirotada died in 1549, the Imagawa captured a son of Oda Nobuhide and exchanged him for Takechiyo, who was taken to Sunpu. He lived there for more than a decade under Imagawa Yoshimoto, came of age, took the name Matsudaira Motoyasu, married a kinswoman of the Imagawa and first went to war as one of their captains.']),
      w(1560, 136.94, 35.065,
        ['大高城（今名古屋市绿区，桶狭间附近）', '桶狭间之战后脱离今川氏', '1560年6月，今川义元率大军西进尾张，元康担任先锋，把军粮运入前线的大高城。义元却在附近的桶狭间遭织田信长奇袭身亡。元康趁乱撤回故城冈崎，结束了十余年的人质生涯，开始自立。'],
        ['Odaka Castle (Midori Ward, Nagoya, near Okehazama)', 'Breaks free of the Imagawa after Okehazama', 'In June 1560 Imagawa Yoshimoto led a large army west into Owari, with Motoyasu in the vanguard carrying supplies into the frontier fort of Odaka. Nearby at Okehazama, Yoshimoto was killed in a surprise attack by Oda Nobunaga. Motoyasu withdrew to his family castle of Okazaki, ending more than a decade as a hostage, and set about making himself independent.'],
        { wiki: { zh: '桶狭间之战', en: 'Battle of Okehazama' } }),
      w(1562, 136.843, 35.216,
        ['清洲城（今爱知县清须市）', '与织田信长结成清洲同盟', '相传1562年，元康前往清洲城与织田信长会面，缔结同盟。这一盟约维持了二十年，信长得以专心西进，元康则向东扩张。他平定三河的一向一揆，统一三河国，改名家康，1566年又获朝廷许可改姓德川。'],
        ['Kiyosu Castle (Kiyosu, Aichi)', 'Allies with Oda Nobunaga', 'Tradition has it that in 1562 Motoyasu visited Kiyosu Castle to seal an alliance with Oda Nobunaga. The pact held for twenty years, freeing Nobunaga to push west while his ally expanded eastward. He put down a rising of Ikko Buddhist leagues, united Mikawa, changed his given name to Ieyasu and in 1566 received court sanction for the surname Tokugawa.']),
      w(1573, 137.7, 34.77,
        ['三方原（今静冈县滨松市）', '三方原之战惨败于武田信玄', '家康1570年把居城迁到远江的滨松。1573年1月，武田信玄的大军从城下经过，家康不顾劝阻出城追击，在三方原台地上被打得大败，折损了许多家臣，本人仅以身免。信玄数月后病死，德川氏才逃过一劫。'],
        ['Mikatagahara (Hamamatsu, Shizuoka)', 'Routed by Takeda Shingen at Mikatagahara', 'Ieyasu had moved his seat to Hamamatsu in Totomi in 1570. In January 1573 the army of Takeda Shingen marched past the castle, and against advice Ieyasu went out to attack it. On the Mikatagahara plateau he was badly beaten, lost many retainers and barely escaped with his life. Shingen died of illness a few months later, sparing the Tokugawa.']),
      w(1575, 137.56, 34.92,
        ['长篠（今爱知县新城市）', '长篠之战大破武田军', '1575年，武田胜赖围攻德川方的长篠城。家康与信长率联军来援，在城西的设乐原筑起木栅，以大量火绳枪迎击武田军的冲锋。武田氏多名宿将阵亡，从此一蹶不振；1582年武田氏灭亡，家康取得骏河。'],
        ['Nagashino (Shinshiro, Aichi)', 'Defeats the Takeda at Nagashino', 'In 1575 Takeda Katsuyori besieged the Tokugawa castle of Nagashino. Ieyasu and Nobunaga came to its relief and, on the Shitaragahara plain to the west, met the Takeda charges from behind wooden palisades with massed arquebus fire. The Takeda lost many of their veteran commanders and never recovered. When the clan was destroyed in 1582, Ieyasu gained Suruga.'],
        { wiki: { zh: '长篠之战', en: 'Battle of Nagashino' } }),
      w(1582, 135.48, 34.575,
        ['堺（今大阪府堺市）', '本能寺之变后穿越伊贺逃归', '1582年6月，家康应信长之邀游览京都、大阪一带，只带了数十名随从。在堺得知信长于本能寺遇害后，他为躲避明智光秀的追兵，翻越伊贺山地（相传由服部半藏等人引路），再由伊势渡海，数日后回到冈崎。随后他乘乱取得甲斐和信浓。'],
        ['Sakai (Osaka Prefecture)', 'Escapes through Iga after the Honno-ji Incident', "In June 1582 Ieyasu was touring the Kyoto and Osaka area at Nobunaga's invitation with only a few dozen attendants. At Sakai he learned that Nobunaga had been killed at Honno-ji. To evade Akechi Mitsuhide's men he crossed the mountains of Iga, guided according to tradition by Hattori Hanzo, and took ship across Ise Bay, reaching Okazaki within days. He then seized Kai and Shinano."]),
      w(1584, 137.05, 35.18,
        ['长久手（今爱知县长久手市）', '小牧·长久手之战对抗秀吉', '信长死后，羽柴（丰臣）秀吉迅速崛起。1584年家康与信长之子织田信雄联手，在尾张的小牧山一带与秀吉对峙。秀吉的一支别动队企图偷袭三河，被家康在长久手截击歼灭。战事未分胜负，年底信雄单独媾和，家康也随之罢兵。'],
        ['Nagakute (Aichi)', 'Faces Hideyoshi in the Komaki-Nagakute campaign', "After Nobunaga's death Hashiba (later Toyotomi) Hideyoshi rose swiftly to power. In 1584 Ieyasu joined Nobunaga's son Oda Nobukatsu against him and the two sides faced each other around Komaki in Owari. When a detachment of Hideyoshi's army tried to raid Mikawa, Ieyasu caught and destroyed it at Nagakute. The campaign ended without a decision after Nobukatsu made a separate peace."]),
      w(1586, 135.526, 34.687,
        ['大坂城（今大阪市）', '赴大坂臣服于丰臣秀吉', '秀吉无法以武力压服家康，便把妹妹朝日姬嫁给他，又送母亲到冈崎做人质。1586年底家康终于前往大坂城，在诸大名面前向秀吉行臣下之礼。同年他把居城迁到骏府，此时已领有三河、远江、骏河、甲斐、信浓五国。'],
        ['Osaka Castle (Osaka)', 'Submits to Toyotomi Hideyoshi at Osaka', 'Unable to subdue Ieyasu by force, Hideyoshi gave him his sister Asahi in marriage and sent his own mother to Okazaki as a hostage. Late in 1586 Ieyasu at last travelled to Osaka Castle and paid homage before the assembled lords. The same year he moved his seat to Sunpu, by now master of five provinces: Mikawa, Totomi, Suruga, Kai and Shinano.']),
      w(1590, 139.752, 35.685,
        ['江户（今东京）', '移封关东，入主江户', '1590年家康随秀吉围攻小田原，北条氏灭亡。秀吉随即命他交出东海五国，改领北条氏的关东旧地，约250万石。8月家康进入江户，当时这里只是海湾边一座破败的小城。他填海造地、开凿水道、营建城下町，为日后的东京奠定了基础。'],
        ['Edo (now Tokyo)', 'Moved to the Kanto, makes Edo his seat', "In 1590 Ieyasu joined Hideyoshi's siege of Odawara, which destroyed the Hojo. Hideyoshi then had him give up his five provinces in exchange for the former Hojo lands in the Kanto, assessed at about 2.5 million koku. That August he entered Edo, then a run-down castle beside the bay, and began reclaiming land, digging canals and laying out a town, the beginnings of Tokyo."],
        { wiki: { zh: '江户城', en: 'Edo Castle' } }),
      w(1600, 136.465, 35.365,
        ['关原（今岐阜县关原町）', '关原之战获胜，掌握天下', '1598年秀吉去世，留下幼子秀赖，家康以五大老之首的身份独揽大权。石田三成等人起兵讨伐，1600年10月21日，东西两军在关原决战。西军的小早川秀秋临阵倒戈，战斗不到一天便见分晓。战后家康大举改易、转封诸大名，成为事实上的天下之主。'],
        ['Sekigahara (Gifu Prefecture)', 'Wins the Battle of Sekigahara', 'Hideyoshi died in 1598 leaving a child heir, Hideyori, and Ieyasu, the senior regent, gathered power into his own hands. Ishida Mitsunari raised a coalition against him, and on 21 October 1600 the eastern and western armies met at Sekigahara, where the defection of Kobayakawa Hideaki decided the battle within a day. Ieyasu then redistributed the domains of the defeated and was master of Japan in all but name.'],
        { event: 'battle-of-sekigahara' }),
      w(1603, 135.748, 35.014,
        ['京都（伏见城、二条城）', '受封征夷大将军，开创江户幕府', '1603年3月，后阳成天皇派敕使到伏见城，任命家康为征夷大将军，他随后在新落成的二条城举行庆贺仪式，江户幕府由此建立。仅过两年，他就把将军之位让给儿子秀忠，以示此位由德川氏世袭，不会交还丰臣家。'],
        ['Kyoto (Fushimi and Nijo castles)', 'Appointed shogun, founding the Edo shogunate', 'In March 1603 envoys of Emperor Go-Yozei came to Fushimi Castle to appoint Ieyasu shogun, and he celebrated the appointment at his newly built Nijo Castle in Kyoto. The Edo shogunate dates from this moment. Only two years later he passed the title to his son Hidetada, making plain that the office would be hereditary in the Tokugawa house and not returned to the Toyotomi.'],
        { wiki: { zh: '二条城', en: 'Nijō Castle' } }),
      w(1607, 138.383, 34.979,
        ['骏府城（今静冈市）', '以“大御所”身份退居骏府', '1607年家康移居重修后的骏府城，以“大御所”的名义继续掌握实权，尤其亲自过问外交与贸易。他任用漂流到日本的英国人威廉·亚当斯（三浦按针）为顾问，准许荷兰和英国商人在平户设商馆，推行朱印船贸易；1612年起下令禁止天主教。'],
        ['Sunpu Castle (Shizuoka)', 'Retires to Sunpu as Ogosho', 'In 1607 Ieyasu moved to the rebuilt Sunpu Castle, where as Ogosho, or retired shogun, he kept real power in his own hands, above all in foreign affairs and trade. He employed the shipwrecked Englishman William Adams as an adviser, licensed Dutch and English trading posts at Hirado and promoted the red-seal ship trade. From 1612 he issued bans on Christianity.']),
      w(1615, 135.526, 34.687,
        ['大坂城', '大坂之阵攻灭丰臣氏', '丰臣秀赖仍据有坚固的大坂城，并招纳了大批浪人。家康以方广寺钟铭为借口，1614年冬率大军围城，议和后填平了外围壕沟；1615年夏再度进攻，6月初城陷，秀赖与其母淀殿自尽。同年幕府颁布《武家诸法度》和一国一城令，以约束诸大名。'],
        ['Osaka Castle', 'Destroys the Toyotomi in the siege of Osaka', 'Toyotomi Hideyori still held the great castle of Osaka and had taken in many masterless samurai. On the pretext of a temple bell inscription, Ieyasu besieged it in the winter of 1614, made peace and had the outer moats filled in, then attacked again in summer 1615. The castle fell in early June and Hideyori and his mother killed themselves. The shogunate then issued its code for the military houses.']),
      w(1616, 138.383, 34.979,
        ['骏府城', '病逝于骏府', '1616年初，家康在外出放鹰后病倒，民间流传是吃了油炸鲷鱼所致，后人多认为是胃癌。6月1日（元和二年四月十七日）他在骏府城去世，享年73岁。遗体先葬于附近的久能山，次年迁往日光，被朝廷追赠“东照大权现”的神号，奉祀于东照宫。'],
        ['Sunpu Castle', 'Dies at Sunpu', 'Ieyasu fell ill early in 1616 after a hawking trip; a popular story blames a dish of fried sea bream, though stomach cancer is thought the likelier cause. He died at Sunpu Castle on 1 June, aged 73. Buried first on nearby Mount Kuno, he was moved the next year to Nikko and enshrined at the Toshogu under the divine title Tosho Daigongen.'],
        { wiki: { zh: '久能山东照宫', en: 'Kunōzan Tōshō-gū' } }),
    ],
    wiki: { zh: '德川家康', en: 'Tokugawa Ieyasu' },
  },
  {
    id: 'matteo-ricci',
    name: { zh: '利玛窦', en: 'Matteo Ricci' },
    birth: 1552, death: 1610,
    title: { zh: '耶稣会传教士', en: 'Jesuit missionary' },
    region: 'europe',
    lineage: 'china',
    sprite: 'ship',
    summary: {
      zh: '意大利耶稣会传教士，明末来华。他以“合儒”的方式传教，着儒服、习汉语，结交徐光启、李之藻等士大夫。他绘制的《坤舆万国全图》向中国人展示了五大洲，与徐光启合译《几何原本》，是中西文化交流史上的关键人物，也是首位获赐葬于北京的西方传教士。',
      en: "Italian Jesuit missionary who came to China in the late Ming. He presented Christianity in terms compatible with Confucianism, dressed as a Chinese scholar, mastered the classical language and befriended officials such as Xu Guangqi and Li Zhizao. His world map, the Kunyu Wanguo Quantu, showed Chinese readers the continents, and with Xu he translated the first six books of Euclid's Elements. A key figure in the exchange between China and Europe, he was the first Western missionary granted a burial place in Beijing by the emperor.",
    },
    route: [
      w(1552, 13.45, 43.3,
        ['马切拉塔（今意大利马尔凯大区）', '生于教皇国马切拉塔', '1552年10月6日，利玛窦生于意大利中部的马切拉塔，父亲是药剂师，家境殷实。他少年时在本城新办的耶稣会学校就读。就在他出生这一年的12月，耶稣会东方传教的开创者沙勿略病逝于广东外海的上川岛，未能进入中国内地。'],
        ['Macerata (Marche, Italy)', 'Born at Macerata in the Papal States', "Ricci was born on 6 October 1552 at Macerata in central Italy, the son of a well-to-do pharmacist, and was educated at the town's new Jesuit school. In December of the year of his birth Francis Xavier, pioneer of the Jesuit missions in Asia, died on Shangchuan Island off the coast of Guangdong without having entered mainland China."]),
      w(1571, 12.48, 41.9,
        ['罗马', '加入耶稣会', '利玛窦16岁到罗马学习法律，1571年8月违背父亲的意愿加入耶稣会。他在罗马学院师从数学家克拉维乌斯，学习几何、天文、制图以及日晷、钟表的制作。这些学问日后成了他打开中国士大夫之门的钥匙。'],
        ['Rome', 'Joins the Society of Jesus', "Ricci came to Rome at sixteen to study law, and in August 1571, against his father's wishes, he entered the Society of Jesus. At the Roman College he studied under the mathematician Christopher Clavius, learning geometry, astronomy, map-making and the construction of sundials and clocks, skills that would later open the doors of Chinese scholars to him."]),
      w(1577, -8.43, 40.21,
        ['科英布拉（葡萄牙）', '候船期间在科英布拉学习', '利玛窦申请赴东方传教获准，1577年离开罗马前往葡萄牙。当时前往亚洲的传教士都须搭乘每年春季出发的葡萄牙印度船队，他在科英布拉大学一边学习葡萄牙语、修读神学，一边等候了数月。'],
        ['Coimbra (Portugal)', 'Studies at Coimbra while waiting for a ship', 'Accepted for the missions in the East, Ricci left Rome for Portugal in 1577. Missionaries bound for Asia had to travel with the Portuguese India fleet, which sailed once a year in spring, and he spent several months at the University of Coimbra learning Portuguese and continuing his theology while he waited.']),
      w(1578, -9.14, 38.72,
        ['里斯本', '启程前往东方', '1578年3月，利玛窦与罗明坚等十余名耶稣会士觐见葡萄牙国王塞巴斯蒂昂后，分乘三艘船离开里斯本。他搭乘的“圣路易”号绕过好望角，在莫桑比克停靠，船舱拥挤闷热，疾病流行，航程将近半年。'],
        ['Lisbon', 'Sets sail for the East', 'In March 1578, after an audience with King Sebastian of Portugal, Ricci left Lisbon with Michele Ruggieri and a dozen other Jesuits in a fleet of three ships. His vessel, the São Luís, rounded the Cape of Good Hope and called at Mozambique; the passage, in crowded and unhealthy conditions, took nearly six months.']),
      w(1578, 73.83, 15.49,
        ['果阿（印度）', '绕好望角抵达印度果阿', '1578年9月13日，利玛窦抵达葡属印度的首府果阿。此后近四年他在果阿和科钦的耶稣会学院继续攻读神学，同时教授拉丁文和希腊文，1580年在科钦晋铎为神父。1582年，耶稣会远东视察员范礼安调他前往澳门。'],
        ['Goa (India)', 'Reaches Goa by way of the Cape of Good Hope', 'Ricci landed at Goa, capital of Portuguese India, on 13 September 1578. For nearly four years he continued his theology at the Jesuit colleges of Goa and Cochin while teaching Latin and Greek, and he was ordained priest at Cochin in 1580. In 1582 Alessandro Valignano, the Jesuit Visitor in the East, summoned him to Macau.'],
        { sea: true, via: [[-18.0, 12.0], [0.0, -18.0], [18.5, -37.0], [40.7, -15.0], [56.0, 2.0]], wiki: { zh: '果阿的教堂和修道院', en: 'Churches and convents of Goa' } }),
      w(1582, 113.54, 22.19,
        ['澳门', '抵达澳门学习汉语', '1582年8月，利玛窦经马六甲抵达澳门。范礼安主张传教士必须先学会中国的语言文字、适应当地风俗，利玛窦遂与先到的罗明坚一起苦学官话和汉字。他凭借在罗马练就的记忆术进步很快，并开始了解中国的典籍和礼俗。'],
        ['Macau', 'Arrives in Macau and studies Chinese', 'Ricci reached Macau by way of Malacca in August 1582. Valignano held that missionaries must first master the Chinese language and adapt to local custom, and Ricci joined Michele Ruggieri, who had arrived earlier, in the hard study of spoken Mandarin and the written characters. Helped by the memory techniques he had learned in Rome, he made rapid progress.'],
        { sea: true, via: [[76.5, 8.0], [80.5, 5.6], [95.0, 6.0], [104.5, 1.4], [109.5, 11.5]] }),
      w(1583, 112.47, 23.05,
        ['肇庆', '获准入居肇庆，绘制中文世界地图', '1583年9月，利玛窦和罗明坚得到两广总督和肇庆知府王泮许可，在肇庆建起住所“仙花寺”，这是耶稣会在中国内地的第一处据点。他陈列自鸣钟、三棱镜和西洋书籍吸引来客，并应王泮之请于1584年绘成中文世界地图《舆地山海全图》。'],
        ['Zhaoqing', 'Settles at Zhaoqing and draws a world map in Chinese', "In September 1583 Ricci and Ruggieri received permission from the viceroy of Guangdong and Guangxi and the prefect Wang Pan to build a house at Zhaoqing, the first Jesuit residence in mainland China. Ricci displayed clocks, prisms and European books to visitors, and in 1584, at Wang Pan's request, he drew his first world map with Chinese captions."]),
      w(1589, 113.6, 24.8,
        ['韶州（今广东韶关）', '移居韶州，改着儒服', '1589年新任两广总督把传教士逐出肇庆，利玛窦辗转获准迁居北面的韶州。常熟士人瞿太素在此拜他为师学习数学，并劝他不要再作僧人打扮。1594年前后，利玛窦蓄起须发，改穿儒士的丝绸长袍，以“西儒”的身份与士大夫往来。'],
        ['Shaozhou (now Shaoguan, Guangdong)', "Moves to Shaozhou and adopts scholar's dress", 'Expelled from Zhaoqing by a new viceroy in 1589, Ricci was allowed to move north to Shaozhou. There the scholar Qu Taisu became his pupil in mathematics and urged him to stop dressing like a Buddhist monk. Around 1594 Ricci let his hair and beard grow and put on the silk robes of a Confucian scholar, presenting himself as a learned man from the West.']),
      w(1595, 118.78, 32.06,
        ['南京', '首次北上南京，被迫折返', '1595年春，利玛窦随一位赴京的兵部官员北上，翻越梅岭，沿赣江而下，途中在险滩翻船，同行的一名年轻同伴溺水身亡。5月底他抵达留都南京，但当时正值中日在朝鲜交战，外国人备受猜疑，相识的官员催他离开，他只得退回江西。'],
        ['Nanjing', 'First journey north to Nanjing ends in retreat', 'In spring 1595 Ricci travelled north with an official of the Ministry of War, crossing the Meiling Pass and descending the Gan River, where his boat capsized in the rapids and a young companion drowned. He reached Nanjing at the end of May, but with China at war with Japan in Korea foreigners were suspect; an official he knew pressed him to leave, and he fell back to Jiangxi.']),
      w(1595, 115.89, 28.68,
        ['南昌', '著《交友论》', '利玛窦在南昌住了三年，与理学名家章潢和两位明朝宗室亲王交往。他应建安王之请，用中文辑译西方先哲论友谊的格言，写成《交友论》，这是他第一部广为流传的中文著作；又撰《西国记法》介绍记忆术，在士人中声名鹊起。'],
        ['Nanchang', 'Writes On Friendship', 'Ricci spent three years at Nanchang, where he moved among scholars such as Zhang Huang and was received by two princes of the Ming imperial clan. For one of them he compiled in Chinese a collection of Western maxims on friendship, Jiaoyou lun, his first widely read Chinese work; he also wrote a treatise on the art of memory, and his reputation among the literati grew.']),
      w(1598, 116.39, 39.91,
        ['北京', '首次进京，未能立足', '1598年，利玛窦随赴京的南京礼部尚书王忠铭沿大运河北上，9月初次到达北京。时值援朝抗倭战事未息，京中无人敢引荐外国人，他停留约两个月后只得南返。归途在运河上度过寒冬，次年初转往南京定居。'],
        ['Beijing', 'First visit to Beijing fails', 'In 1598 Ricci went north along the Grand Canal with Wang Zhongming, the Nanjing Minister of Rites, and saw Beijing for the first time that September. With the war against Japan in Korea still unfinished, no one dared to sponsor a foreigner, and after about two months he turned back, wintering on the way south and settling in Nanjing early the next year.']),
      w(1599, 118.78, 32.06,
        ['南京', '结交士大夫，声名渐著', '1599年利玛窦在南京购屋定居。他与高僧雪浪洪恩公开辩论，结识思想家李贽，并向前来求教的士人讲解天文、数学，展示地球仪和天文仪器。后来成为他最重要合作者的徐光启，也在这一时期与他初次相识。'],
        ['Nanjing', 'Wins friends among the scholar-officials', "Ricci bought a house in Nanjing in 1599. He held a public debate with the eminent Buddhist monk Xuelang Hong'en, met the unorthodox thinker Li Zhi, and explained astronomy and mathematics to scholars who came to see his globes and instruments. It was in these years that he first met Xu Guangqi, later his most important collaborator."]),
      w(1600, 115.7, 36.84,
        ['临清（今山东临清）', '北上途中被税监马堂扣留', '1600年5月，利玛窦与西班牙籍耶稣会士庞迪我携贡物再度沿运河北上。7月船到临清，督税太监马堂把他们连人带物截留，后又移至天津关押近半年，其间搜出的耶稣受难像一度被疑为害人的巫蛊之物。直到万历皇帝下旨宣召，他们才得以脱身。'],
        ['Linqing (Shandong)', 'Detained on the way north by the eunuch Ma Tang', 'In May 1600 Ricci set out again up the Grand Canal with the Spanish Jesuit Diego de Pantoja, carrying gifts for the emperor. At Linqing in July the eunuch tax commissioner Ma Tang seized them and then held them at Tianjin for almost six months; a crucifix among their things was taken for an instrument of sorcery. They were freed only when the Wanli Emperor sent for them.']),
      w(1601, 116.39, 39.91,
        ['北京', '向万历皇帝进献自鸣钟等，获准长居北京', '1601年1月24日，利玛窦进入北京，进献天主像、圣母像、自鸣钟、西洋琴和《万国图志》等。深居宫中的万历皇帝始终没有召见他，却很喜欢自鸣钟，命他入宫教太监调试钟表和弹琴，默许他留居京城，并由朝廷按月供给钱米。'],
        ['Beijing', 'Presents clocks to the emperor and is allowed to stay', 'Ricci entered Beijing on 24 January 1601 and presented religious paintings, two chiming clocks, a clavichord and an atlas. The reclusive Wanli Emperor never received him in person, but he was delighted with the clocks and had Ricci teach palace eunuchs to maintain them and to play the clavichord. Ricci was allowed to remain in the capital with a stipend from the court.'],
        { event: 'ricci-in-beijing' }),
      w(1602, 116.39, 39.91,
        ['北京', '刊刻《坤舆万国全图》', '1602年，在工部官员李之藻协助下，利玛窦增订世界地图，刻成六幅屏风式的《坤舆万国全图》。图中把中国置于中央附近，标出五大洲和经纬线，并以中文注解各地风土和地圆之说。此图后来传入朝鲜和日本，影响深远。'],
        ['Beijing', 'Publishes the Kunyu Wanguo Quantu world map', 'In 1602, with the help of the official Li Zhizao, Ricci produced an enlarged world map, the Kunyu Wanguo Quantu, printed from woodblocks on six large panels. It placed China near the centre, showed the continents with lines of latitude and longitude, and explained in Chinese the customs of distant lands and the roundness of the earth. Copies later reached Korea and Japan.'],
        { wiki: { zh: '坤舆万国全图', en: 'Kunyu Wanguo Quantu' } }),
      w(1605, 116.374, 39.9,
        ['北京（宣武门内）', '在宣武门内购屋建堂', '1603年利玛窦刊行《天主实义》，以对话体援引儒家经典论证天主教义。1605年，他在宣武门内购得一处宅院，作为耶稣会士的固定住所并设小教堂，这就是北京南堂的前身。此时京城的教徒渐增，其中不乏官员。'],
        ['Beijing (inside the Xuanwu Gate)', 'Establishes a residence and chapel by the Xuanwu Gate', "In 1603 Ricci published Tianzhu shiyi (The True Meaning of the Lord of Heaven), a dialogue arguing for Christian doctrine with the help of the Confucian classics. In 1605 he bought a compound just inside the Xuanwu Gate as a permanent Jesuit residence with a small chapel, the origin of Beijing's South Church. Converts in the capital were increasing, some officials among them."],
        { wiki: { zh: '宣武门天主堂', en: 'Cathedral of the Immaculate Conception, Beijing' } }),
      w(1607, 116.39, 39.91,
        ['北京', '与徐光启合译《几何原本》前六卷', '徐光启1604年中进士后入翰林院，常来向利玛窦问学。两人以克拉维乌斯的拉丁文注本为底本，由利玛窦口述、徐光启笔录，历时一年多，于1607年译成欧几里得《几何原本》前六卷。“几何”“点”“线”“面”“平行线”等译名沿用至今。'],
        ['Beijing', "Translates Euclid's Elements with Xu Guangqi", "After passing the highest examination in 1604 Xu Guangqi joined the Hanlin Academy and came often to study with Ricci. Working from Clavius's Latin edition, with Ricci explaining aloud and Xu writing, they completed the first six books of Euclid's Elements in 1607 after more than a year's labour. Many of the Chinese geometrical terms they coined are still in use."],
        { wiki: { zh: '几何原本', en: "Euclid's Elements" } }),
      w(1610, 116.39, 39.91,
        ['北京', '病逝，获赐葬于北京', '1610年5月11日，利玛窦因劳累过度在北京病逝，享年57岁。按惯例客死中国的外国人须归葬澳门，经庞迪我上疏和朝中官员斡旋，万历皇帝破例赐阜成门外的栅栏地为墓地。此后数百年间，汤若望、南怀仁等传教士也陆续葬于此处。'],
        ['Beijing', 'Dies and is granted burial in Beijing', 'Ricci died in Beijing on 11 May 1610, aged 57, worn out by overwork. Foreigners who died in China were normally taken to Macau for burial, but after a petition by Diego de Pantoja, supported by senior officials, the Wanli Emperor granted a plot at Zhalan outside the Fucheng Gate. Later missionaries, among them Adam Schall and Ferdinand Verbiest, were buried there beside him.'],
        { wiki: { zh: '滕公栅栏', en: 'Zhalan Cemetery' } }),
    ],
    wiki: { zh: '利玛窦', en: 'Matteo Ricci' },
  },
];
